L2_1 = {}
L2_1.m_CutScenKey_Talk = "ESPR2_ACT2_INTERLUDE1@2#Talk"
L2_1.m_CutScenProcessKey = 2
L2_1.m_CutScenID = 4800201
L2_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_Face = "UNIT_PRIDE"
L2_1.m_CharStrID = "EDEL_ESPR_SHADOW_NULL"
L2_1.m_Pos = "L"
L2_1.m_bCharPinup = true
L2_1.m_bCharPinupEasingTime = 0.3
L2_1.m_Talk_KOREA = "취향과 다르게 아기자기한 곳에 머물고 계셨네요, 세라펠."
L2_1.m_fTalkTime = 0.03
L2_1.m_Talk_JPN = "好みとは違って可愛らしいところに住んでいるんですね、セラフェル。"
L2_1.m_Talk_ENG = "What a cute and cozy place you're staying at, Serapel. It doesn't really suit you, right?"
L2_1.m_Talk_TWN = "跟你的喜好不同，你住的地方很可愛呢，塞拉費爾。"
L2_1.m_Talk_THA = "ที่ที่เจ้าอยู่มันน่ารักและสบายชะมัดเลยนะเซราเพล ดูไม่เหมาะกับเจ้าเลยว่ามั้ย?"
L2_1.m_Talk_VTN = "Serapel, chỗ cô ở quả là dễ thương và ấm cúng. Chẳng phải nó rất hợp với cô sao?"
L2_1.m_Talk_SCN = "跟你的嗜好不同，住的地方倒是很精致可爱呢，塞拉费尔。"
L2_1.m_Talk_DEU = "Sie wohnten an einem recht hübschen Ort. Das hätte ich bei Ihrem Geschmack gar nicht erwartet, Serapel."
L2_1.m_Talk_FRA = "C'est vraiment cosy ici, Serapel. Étrange, ça ne correspond pas vraiment à votre personnalité."
L3_1 = {}
L3_1.m_CutScenKey_Talk = "ESPR2_ACT2_INTERLUDE1@3#Talk"
L3_1.m_CutScenProcessKey = 3
L3_1.m_CutScenID = 4800201
L3_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "SERAPEL_QLIPHOTH_NULL_NULL"
L3_1.m_Pos = "R"
L3_1.m_bCharPinup = true
L3_1.m_bCharPinupEasingTime = 0.3
L3_1.m_Talk_KOREA = "그렇지. 주인이 없을 때는 이런 곳에라도 머물러야 마음이 진정돼."
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "そうね。マスターがいない時にはこんなところにでもいないと心が落ち着かないの。"
L3_1.m_Talk_ENG = "Yes. When my master isn't around, staying in a place like this helps to calm my nerves."
L3_1.m_Talk_TWN = "是啊。主人不在的時候，至少要待在這樣的地方，我的心才會平靜。"
L3_1.m_Talk_THA = "ใช่ ตอนที่เจ้านายข้าไม่อยู่ การอยู่ในที่แบบนี้ทำให้ใจข้าสงบได้"
L3_1.m_Talk_VTN = "Ừ. Khi chủ nhân của tôi không ở bên, ở nơi thế này sẽ giúp thư giãn những sợi dây thần kinh căng thẳng của tôi."
L3_1.m_Talk_SCN = "没错。主人不在的时候，至少要待在这样的地方，我的心才会平静。"
L3_1.m_Talk_DEU = "Ja. Wenn mein Meister nicht in der Nähe ist, hilft der Aufenthalt an einem Ort wie diesem, meine Nerven zu beruhigen."
L3_1.m_Talk_FRA = "Quand mon maître n'est pas là, rester dans un endroit comme celui-ci m'aide à me détendre."
L4_1 = {}
L4_1.m_CutScenKey_Talk = "ESPR2_ACT2_INTERLUDE1@4#Talk"
L4_1.m_CutScenProcessKey = 4
L4_1.m_CutScenID = 4800201
L4_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_Face = "UNIT_LAUGH"
L4_1.m_CharStrID = "SERAPEL_QLIPHOTH_NULL_NULL"
L4_1.m_Pos = "R"
L4_1.m_bCharPinup = true
L4_1.m_bCharPinupEasingTime = 0.3
L4_1.m_Talk_KOREA = "아아, 흥분돼서 당장이라도 확인하고 싶구나."
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "ああ、興奮してしまって、今すぐにでも確認したくてたまらないわ。"
L4_1.m_Talk_ENG = "Ahh... I'm so aroused I want to check right away."
L4_1.m_Talk_TWN = "啊啊，我太激動了，好想馬上就確認啊。"
L4_1.m_Talk_THA = "อาาห์... ข้าตื่นเต้นจนอยากตรวจดูเดี๋ยวนี้เลย"
L4_1.m_Talk_VTN = "Ahh... Tôi phấn khích đến mức muốn khám phá ngay lập tức."
L4_1.m_Talk_SCN = "啊啊，真是让人战栗，好想马上就去确认啊。"
L4_1.m_Talk_DEU = "Ahh. Ich bin so aufgeregt, dass ich es sofort überprüfen möchte."
L4_1.m_Talk_FRA = "Ah... Je suis tellement excitée, j'aimerais savoir tout de suite."
L5_1 = {}
L5_1.m_CutScenKey_Talk = "ESPR2_ACT2_INTERLUDE1@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 4800201
L5_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "SERAPEL_QLIPHOTH_NULL_NULL"
L5_1.m_Pos = "R"
L5_1.m_bCharPinup = true
L5_1.m_bCharPinupEasingTime = 0.3
L5_1.m_Talk_KOREA = "그 아이가……. 메이의 핏줄이 내게 다시 한 번 타오르는 고통을 느끼게 해 줄 수 있을지."
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "あの子が……メイの血筋が私にもう一度燃え上げるような苦痛を味わわせてくれるかどうか。"
L5_1.m_Talk_ENG = "That child... I want to see if May's bloodline will gift me that burning pain once more."
L5_1.m_Talk_TWN = "那孩子……梅伊的血脈究竟能否讓我再次感受到燃燒的痛苦。"
L5_1.m_Talk_THA = "เด็กนั่น... ข้าอยากเห็นเสียจริงว่าสายเลือดของเมย์จะแผดเผาข้าให้เจ็บปวดแบบนั้นได้อีกมั้ย"
L5_1.m_Talk_VTN = "Đứa trẻ đó... Tôi muốn xem liệu dòng máu của May có mang lại cho tôi đau đớn cháy bỏng đó một lần nữa hay không."
L5_1.m_Talk_SCN = "那孩子……梅伊的血脉究竟能否让我再次感受到燃烧的痛苦。"
L5_1.m_Talk_DEU = "Dieses Kind ... Ich möchte sehen, ob Mays Blutlinie mich noch einmal diesen brennenden Schmerz verspüren lässt."
L5_1.m_Talk_FRA = "Cette enfant... La lignée de May saura-t-elle m'offrir une douleur brûlante et exquise, une fois de plus ?"
L6_1 = {}
L6_1.m_CutScenKey_Talk = "ESPR2_ACT2_INTERLUDE1@6#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 4800201
L6_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_LAUGH"
L6_1.m_CharStrID = "EDEL_ESPR_SHADOW_NULL"
L6_1.m_Pos = "L"
L6_1.m_bCharPinup = true
L6_1.m_bCharPinupEasingTime = 0.3
L6_1.m_Talk_KOREA = "너무 걱정 마세요. 늑대의 송곳니가 기다리고 있을 테니까요."
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "そう心配することはありません。狼の牙が待っているはずですから。"
L6_1.m_Talk_ENG = "Don't worry so much. The Wolf's fang will be waiting for you."
L6_1.m_Talk_TWN = "別太擔心了。狼牙應該在等著你呢。"
L6_1.m_Talk_THA = "ไม่ต้องห่วงนักหรอก เขี้ยวหมาป่ารอขย้ำเจ้าอยู่แล้ว"
L6_1.m_Talk_VTN = "Đừng lo quá. Nanh Sói sẽ chờ đón cô."
L6_1.m_Talk_SCN = "不用这么担心。还有狼牙在等着你呢。"
L6_1.m_Talk_DEU = "Machen Sie sich nicht zu viele Sorgen. Der Fangzahn des Wolfes wird auf Sie warten."
L6_1.m_Talk_FRA = "Ne vous échauffez pas tant que ça. Les crocs de la louve attendront."
L7_1 = {}
L7_1.m_CutScenKey_Talk = "ESPR2_ACT2_INTERLUDE1@7#Talk"
L7_1.m_CutScenProcessKey = 7
L7_1.m_CutScenID = 4800201
L7_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "SERAPEL_QLIPHOTH_NULL_NULL"
L7_1.m_Pos = "R"
L7_1.m_bCharPinup = true
L7_1.m_bCharPinupEasingTime = 0.3
L7_1.m_Talk_KOREA = "후후, 쉽게 넘길 생각도 없으면서 말만큼은 여전히 달콤하구나."
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "ふふ、簡単に渡すつもりもないくせに、言葉だけは相変わらずうまいのね。"
L7_1.m_Talk_ENG = "Fu fu. Your hollow words are like honey, even though I know you don't want to give her up so easily."
L7_1.m_Talk_TWN = "呵呵，你明明不會輕易讓給我，卻還說得這麼好聽。"
L7_1.m_Talk_THA = "หึหึ ถ้อยคำกลวงเปล่าของเจ้านี่ดั่งน้ำผึ้ง แม้ข้ารู้ว่าเจ้าจะไม่ยอมปล่อยนางไปง่ายๆ ก็เถอะ"
L7_1.m_Talk_VTN = "Fufu. Mấy lời rỗng tuếch của cô ngọt như mía lùi ấy, dù tôi rõ mười mươi là cô chẳng đời nào chịu giao cô ta ra dễ dàng như vậy."
L7_1.m_Talk_SCN = "呵呵，你明明不会轻易让给我，却还说得这么好听。"
L7_1.m_Talk_DEU = "Hoho. Du hast sowieso nicht die Absicht, sie mir so einfach zu überlassen, aber trotzdem danke für die süßen Worte."
L7_1.m_Talk_FRA = "Hu hu. Je sais bien que tu ne la cédera pas aussi facilement."
L8_1 = {}
L8_1.m_CutScenProcessKey = 8
L8_1.m_CutScenID = 4800201
L8_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L8_1.m_bWaitClick = false
L8_1.m_fWaitTime = 0
L8_1.m_bClear = true
L9_1 = {}
L9_1.m_CutScenKey_Talk = "ESPR2_ACT2_INTERLUDE1@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 4800201
L9_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Face = "UNIT_IDLE"
L9_1.m_CharStrID = "SERAPEL_QLIPHOTH_NULL_NULL"
L9_1.m_Pos = "C"
L9_1.m_Talk_KOREA = "하지만 정말로 왔군. 속삭이는 자의 사도에게 전해 들었을 때는 믿지 않았건만."
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "それにしても、本当に来るとはね。囁く者の使徒から聞いた時には信じていなかったけど。"
L9_1.m_Talk_ENG = "Anyway, you did come to me. I didn't believe what the Apostle of the Whisperer told though."
L9_1.m_Talk_TWN = "不過你真的來了啊。低語者的使徒告訴我時我還不相信。"
L9_1.m_Talk_THA = "แต่ในที่สุดมันก็มาหาข้าจนได้ ทั้งที่ข้าไม่เชื่อถอยคำจากสาวกของผู้กระซิบนั่น"
L9_1.m_Talk_VTN = "Dù sao, cô cuối cùng đã đến với tôi. Dù tôi chẳng tin lời nào về Kẻ Thì Thầm của Tông Đồ."
L9_1.m_Talk_SCN = "不过你真的来了。我还以为低语者的使徒是在骗我。"
L9_1.m_Talk_DEU = "Wie auch immer, du bist also wirklich zu mir gekommen. Ich habe jedoch nicht geglaubt, was der Apostel des Flüsterers mir erzählt hat."
L9_1.m_Talk_FRA = "Quoi qu'il en soit, tu es venue à moi. Quand l'Apôtre du Murmureur me l'a annoncé, je n'y croyais pas vraiment."
L10_1 = {}
L10_1.m_CutScenKey_Talk = "ESPR2_ACT2_INTERLUDE1@10#Talk"
L10_1.m_CutScenProcessKey = 10
L10_1.m_CutScenID = 4800201
L10_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_LAUGH"
L10_1.m_CharStrID = "SERAPEL_QLIPHOTH_NULL_NULL"
L10_1.m_Pos = "C"
L10_1.m_Talk_KOREA = "네 애완동물 건은 미안하게 됐다. 오랜만에 깨어난 나머지 조금 과하게 사용했던가."
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "あなたのペットの件は悪かったわ。久々に目覚めたせいか、少し力を使いすぎてしまったみたい。"
L10_1.m_Talk_ENG = "I'm sorry about what happened to your pet. Did I overuse it after I awoke from a long slumber?"
L10_1.m_Talk_TWN = "你的寵物那件事，真對不起了。因為太久沒有醒來，我好像有點使用過度了。"
L10_1.m_Talk_THA = "ข้าเสียใจกับเรื่องที่สัตว์เลี้ยงของเจ้าเจอด้วยนะ ตอนฟื้นจากนิทราแสนนานเจ้าใช้งานมันหนักไปรึเปล่า?"
L10_1.m_Talk_VTN = "Tôi rất tiếc về điều đã xảy ra với thú cưng của cô. Tôi đã lạm dụng nó hơi nhiều sau khi tôi tỉnh dậy từ giấc ngủ dài nhỉ?"
L10_1.m_Talk_SCN = "你的宠物的那件事，真是对不起。因为太久没有醒来，我好像有点使用过度了，呼呼。"
L10_1.m_Talk_DEU = "Es tut mir leid, was mit deinem Haustier passiert ist. Habe ich es übermäßig benutzt, nachdem ich aus diesem langen Schlaf erwacht bin?"
L10_1.m_Talk_FRA = "Désolée pour ce qui est arrivé à ton petit animal de compagnie. J'en ai peut-être un peu trop fait à mon réveil après ce si long sommeil ?"
L11_1 = {}
L11_1.m_CutScenKey_Talk = "ESPR2_ACT2_INTERLUDE1@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 4800201
L11_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "SERAPEL_QLIPHOTH_NULL_NULL"
L11_1.m_Pos = "C"
L11_1.m_Talk_KOREA = "확실히 나쁘진 않았어. 그토록 강한 생기를 지닌 자는 어떻게 찾았지?"
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "確かに悪くはなかったわ。あれほど強い生気を持った人間をどうやって探し出したの？"
L11_1.m_Talk_ENG = "It wasn't bad at all. How did you come across someone with such vigor?"
L11_1.m_Talk_TWN = "不過確實很不錯。那麼充滿活力的人，你是怎麼找到的？"
L11_1.m_Talk_THA = "มันก็ไม่ได้แย่เลยนะ เจ้าไปเจอคนมีชีวิตชีวาแบบนั้นได้ยังไงน่ะ?"
L11_1.m_Talk_VTN = "Nó không tệ chút nào. Sao mà cô lại gặp được một người có sức sống như vậy?"
L11_1.m_Talk_SCN = "不过确实很不错。那么充满活力的人类，你是怎么找到的？"
L11_1.m_Talk_DEU = "Es war definitiv nicht schlecht. Wie hast du überhaupt jemanden mit so starker Vitalität gefunden?"
L11_1.m_Talk_FRA = "C'était pas mal du tout. Comment as-tu fait pour trouver quelqu'un avec une telle vigueur ?"
L12_1 = {}
L12_1.m_CutScenKey_Talk = "ESPR2_ACT2_INTERLUDE1@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 4800201
L12_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_PRIDE"
L12_1.m_CharStrID = "EDEL_ESPR_SHADOW_NULL"
L12_1.m_Pos = "C"
L12_1.m_Talk_KOREA = "……잠시 협력하는 사이에게 거기까지 답변해 드릴 이유는 없을 것 같네요."
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "……一時的に協力する間柄で、そこまで答えなければならない理由はないと思います。"
L12_1.m_Talk_ENG = "...We don't see why we have to answer you when our brief partnership is coming to an end."
L12_1.m_Talk_TWN = "……大家只是暫時合作的關係，我們好像沒理由回答你的問題。"
L12_1.m_Talk_THA = "พวกเราไม่เห็นความจำเป็นต้องตอบอะไรเจ้า ในเมื่อการเป็นพันธมิตรสั้นๆ ของเราก็ต้องสิ้นสุดลงอยู่ดี"
L12_1.m_Talk_VTN = "Chúng tôi chẳng hiểu tại sao phải trả lời cô khi mối quan hệ hợp tác ngắn ngủi của chúng ta sắp kết thúc."
L12_1.m_Talk_SCN = "……大家只是暂时合作的关系，我们好像没理由回答你的问题呢。"
L12_1.m_Talk_DEU = "... Wir glauben nicht, dass wir diese Frage beantworten müssen, wenn sich unsere kurze Zusammenarbeit sowieso dem Ende neigt."
L12_1.m_Talk_FRA = "... Notre partenariat touche à sa fin, je n'ai aucune raison de vous répondre."
L13_1 = {}
L13_1.m_CutScenKey_Talk = "ESPR2_ACT2_INTERLUDE1@13#Talk"
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 4800201
L13_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "EDEL_ESPR_SHADOW_NULL"
L13_1.m_Pos = "C"
L13_1.m_Talk_KOREA = "질문의 의도가 저희를 자극해서 고통 받기 위해서라는 점 때문에, 더더욱."
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "質問の意図が我々を刺激して苦痛を受けようとするためなら、なおさら。"
L13_1.m_Talk_ENG = "Also, because your intention is to use our response to feel pain."
L13_1.m_Talk_TWN = "而且如果你提問的意圖是刺激我們讓我們痛苦，那我們就更沒必要回答了。"
L13_1.m_Talk_THA = "นอกจากนั้น เจ้ายังเจตนาใช้การตอบสนองของพวกเราไปสร้างความเจ็บปวดอีกด้วย"
L13_1.m_Talk_VTN = "Ngoài ra, còn là vì cô cố tình lợi dụng phản ứng của chúng tôi để cảm nhận nỗi đau."
L13_1.m_Talk_SCN = "而且如果你提问只是想我们感到刺痛，那就更没必要回答了。"
L13_1.m_Talk_DEU = "Vor allem, weil die Frage uns provozieren und leiden lassen soll."
L13_1.m_Talk_FRA = "Encore moins quand je sais que vous comptez utiliser note réponse pour vous donner de la douleur."
L14_1 = {}
L14_1.m_CutScenKey_Talk = "ESPR2_ACT2_INTERLUDE1@14#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 4800201
L14_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Face = "UNIT_LAUGH"
L14_1.m_CharStrID = "SERAPEL_QLIPHOTH_NULL_NULL"
L14_1.m_Pos = "C"
L14_1.m_Talk_KOREA = "후훗. 떨어져 나온 단말 주제에 영리한 척 굴긴."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "ふふっ。遠隔端末風情がずいぶんお利巧なことを言うのね。"
L14_1.m_Talk_ENG = "Hah hah. A mere piece trying to be clever, I see."
L14_1.m_Talk_TWN = "呵呵，只是一個分身而已，裝什麼聰明。"
L14_1.m_Talk_THA = "ฮ่าฮ่า เป็นแค่ร่างโคลนแต่อยากทำตัวมีสมองสินะ เข้าใจแล้ว"
L14_1.m_Talk_VTN = "Hahahah. Tôi hiểu rồi, một bản sao đơn thuần đang cố tỏ ra thông minh hả."
L14_1.m_Talk_SCN = "呵呵，只是一个分身而已，装什么聪明。"
L14_1.m_Talk_DEU = "Haha. Du bist nur ein Klon, der versucht, schlau zu wirken."
L14_1.m_Talk_FRA = "Hu hu. Pour un simple clone, tu as de la jugeote."
