L16_1 = {}
L16_1.m_CutScenKey_Talk = "ESPR2_ACT2_INTERLUDE1@16#Talk"
L16_1.m_CutScenProcessKey = 16
L16_1.m_CutScenID = 4800201
L16_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Face = "UNIT_IDLE"
L16_1.m_CharStrID = "EDEL_ESPR_SHADOW_NULL"
L16_1.m_Pos = "C"
L16_1.m_Talk_KOREA = "그래서, 새로운 <color=#ffd34c>주인</color>은 어디에 있나요?"
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "ところで、新しい<color=#ffd34c>マスター</color>はどこにいるのですか？"
L16_1.m_Talk_ENG = "So? Where is your new <color=#ffd34c>master</color>?"
L16_1.m_Talk_TWN = "所以，新<color=#ffd34c>主人</color>在哪裡？"
L16_1.m_Talk_THA = "แล้วไงล่ะ? ไหนนะ<color=#ffd34c>เจ้านาย</color>ใหม่ของเจ้า?"
L16_1.m_Talk_VTN = "Thì sao nào? Mà <color=#ffd34c>chủ nhân</color> mới của cô ở đâu?"
L16_1.m_Talk_SCN = "所以，你的新<color=#ffd34c>主人</color>呢？"
L16_1.m_Talk_DEU = "Also, wo ist Ihr neuer <color=#ffd34c>Meister</color>?"
L16_1.m_Talk_FRA = "Alors ? Où est votre nouveau <color=#ffd34c>maître</color> ?"
L17_1 = {}
L17_1.m_CutScenKey_Talk = "ESPR2_ACT2_INTERLUDE1@17#Talk"
L17_1.m_CutScenProcessKey = 17
L17_1.m_CutScenID = 4800201
L17_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_IDLE"
L17_1.m_CharStrID = "SERAPEL_QLIPHOTH_NULL_NULL"
L17_1.m_Pos = "C"
L17_1.m_Talk_KOREA = "잠시 협력하는 사이에게 거기까지 답변해 줘야 하던가?"
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "一時的に協力する間柄で、そこまで答える必要があるのかしら。"
L17_1.m_Talk_ENG = "I don't need to answer you too, do I?"
L17_1.m_Talk_TWN = "大家只是暫時合作的關係，我有必要回答你的問題嗎？"
L17_1.m_Talk_THA = "ข้าเองก็ไม่จำเป็นต้องตอบเจ้าใช่มั้ยนะ?"
L17_1.m_Talk_VTN = "Tôi cũng chẳng cần trả lời cô nhỉ?"
L17_1.m_Talk_SCN = "大家只是暂时合作的关系，我有必要回答你的问题吗？"
L17_1.m_Talk_DEU = "Ich muss dir auch nicht antworten, oder?"
L17_1.m_Talk_FRA = "Rien ne m'oblige à te répondre, si ?"
L18_1 = {}
L18_1.m_CutScenKey_Talk = "ESPR2_ACT2_INTERLUDE1@18#Talk"
L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 4800201
L18_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_Face = "UNIT_LAUGH"
L18_1.m_CharStrID = "EDEL_ESPR_SHADOW_NULL"
L18_1.m_Pos = "C"
L18_1.m_Talk_KOREA = "그렇네요. 이번에는 한 입에 삼켜지지 않길 바랄게요."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "それもそうですね。今度はひと口にのみ込まれないといいですね。"
L18_1.m_Talk_ENG = "Fair enough. We hope she doesn't get swallowed in one bite this time."
L18_1.m_Talk_TWN = "是啊。希望這次不會被我們一口吞掉。"
L18_1.m_Talk_THA = "ยุติธรรมดี หวังว่าคราวนี้นางจะไม่โดนกัดคำเดียวม้วยหรอกนะ"
L18_1.m_Talk_VTN = "Công bằng đấy chứ. Chúng tôi hy vọng lần này cô ấy không bị nuốt gọn."
L18_1.m_Talk_SCN = "是啊。希望这次不会被我们一口吞掉。"
L18_1.m_Talk_DEU = "Stimmt schon. Wir hoffen nur, dass sie dieses Mal nicht mit einem einzigen Bissen verschlungen wird."
L18_1.m_Talk_FRA = "Pas faux. Nous espérons qu'elle ne se fera pas dévorer d'une simple bouchée, cette fois-ci."
L19_1 = {}
L19_1.m_CutScenKey_Talk = "ESPR2_ACT2_INTERLUDE1@19#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 4800201
