L19_1.m_CharStrID = "EDEL_ESPR_SHADOW_NULL"
L19_1.m_Pos = "C"
L19_1.m_Talk_KOREA = "아. 잠시만요."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "あ、少々お待ちを。"
L19_1.m_Talk_ENG = "Oh, one moment, please."
L19_1.m_Talk_TWN = "啊，等一下。"
L19_1.m_Talk_THA = "อ้อ รอสักครู่นะ"
L19_1.m_Talk_VTN = "Oh, làm ơn chờ chút."
L19_1.m_Talk_SCN = "啊，等一下。"
L19_1.m_Talk_DEU = "Oh! Einen Augenblick."
L19_1.m_Talk_FRA = "Oh, un instant."
