L23_1 = {}
L23_1.m_CutScenKey_Talk = "ESPR2_ACT2_INTERLUDE1@23#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 4800201
L23_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_Face = "UNIT_IDLE"
L23_1.m_CharStrID = "EDEL_ESPR_NULL_NULL"
L23_1.m_Pos = "L"
L23_1.m_Talk_KOREA = "네, 교수님. 말씀하세요."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "はい、教授。どうぞ。"
L23_1.m_Talk_ENG = "Yes, Professor?"
L23_1.m_Talk_TWN = "喂，教授，你請說。"
L23_1.m_Talk_THA = "ค่ะ ศาสตราจารย์"
L23_1.m_Talk_VTN = "Vâng, thưa Giáo Sư?"
L23_1.m_Talk_SCN = "喂，教授，你请说。"
L23_1.m_Talk_DEU = "Ja, Professor?"
L23_1.m_Talk_FRA = "Professeur ? Je vous écoute."
L24_1 = {}
L24_1.m_CutScenKey_Talk = "ESPR2_ACT2_INTERLUDE1@24#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 4800201
L24_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "PROFESSOR_NPC_NULL_NULL"
L24_1.m_Pos = "R"
L24_1.m_Talk_KOREA = "집중하고 계셨군요. 위험한 곳에 가셨나 봅니다."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "集中しておられたのですね。危険なところにいらっしゃったのですか。"
L24_1.m_Talk_ENG = "I see you were concentrating. Are you somewhere dangerous?"
L25_1 = "你看起來很專注，是去了很危險的地方嗎。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "เห็นกำลังใช้สมาธิอยู่ คุณอยู่ที่อันตรายที่ไหนรึเปล่าครับ?"
L24_1.m_Talk_THA = L25_1
L25_1 = "Cô chăm chỉ quá. Cô có đang ở chỗ nào nguy hiểm không?"
L24_1.m_Talk_VTN = L25_1
L25_1 = "你看起来很专注，是去了很危险的地方吗。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Du scheinst konzentriert zu sein. Bist du an einem gefährlichen Ort?"
L24_1.m_Talk_DEU = L25_1
L25_1 = "Vous semblez tendue. Un danger dont je devrais m'inquiéter ?"
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "ESPR2_ACT2_INTERLUDE1@25#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 25
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 4800201
L25_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_PRIDE"
L25_1.m_CharStrID = "EDEL_ESPR_NULL_NULL"
L25_1.m_Pos = "L"
L26_1 = "괜찮아요. <color=#ffd34c>저희</color>는 하나지만 여럿이니까요."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "大丈夫です。<color=#ffd34c>我々</color>は一つであり複数ですから。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "We're all right. <color=#ffd34c>We</color> are one, but also many."
L25_1.m_Talk_ENG = L26_1
L26_1 = "沒關係。因為<color=#ffd34c>我們</color>既是一個整體，也是許多個體。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ฉันไม่เป็นไรค่ะ <color=#ffd34c>พวกเรา</color>มีหนึ่งเดียว แต่ก็มีมากมายด้วย"
L25_1.m_Talk_THA = L26_1
L26_1 = "Tôi ổn cả. <color=#ffd34c>Chúng tôi</color> là một cá thể, nhưng cũng là một tập thể."
L25_1.m_Talk_VTN = L26_1
L26_1 = "没关系。因为<color=#ffd34c>我们</color>既是一个整体，也是许多个体。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Kein Sorge. <color=#ffd34c>Wir</color> sind zwar eins, aber auch viele."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Non, tout va bien. <color=#ffd34c>Nous</color> sommes un, et plusieurs à la fois."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "ESPR2_ACT2_INTERLUDE1@26#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 26
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 4800201
L26_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "EDEL_ESPR_NULL_NULL"
L26_1.m_Pos = "L"
L27_1 = "그보다 개인적인 용무를 해결하러 간다고 하지 않으셨나요? 무슨 일이시죠?"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "それより、個人的な用事を解決しに行くとおっしゃいませんでしたか？　何かありましたか？"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Anyway, didn't you say you were taking care of personal matters? Is something wrong?"
L26_1.m_Talk_ENG = L27_1
L27_1 = "對了，你不是說要去辦私事嗎？是什麼事？"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ว่าแต่ คุณบอกว่าจัดการเรื่องส่วนตัวอยู่ไม่ใช่เหรอคะ? มีอะไรผิดปกติรึเปล่า?"
L26_1.m_Talk_THA = L27_1
L27_1 = "Dù sao, không phải ngài nói mình có chuyện riêng à? Có chuyện gì phải không?"
L26_1.m_Talk_VTN = L27_1
L27_1 = "对了，你不是说要去办私事吗？是什么事？"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Wie auch immer, haben Sie nicht gesagt, dass Sie sich um eine persönliche Angelegenheiten kümmern? Gibt es ein Problem?"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Mais dites-moi, n'étiez-vous pas parti régler des affaires personnelles ? Quelque chose ne va pas ?"
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "ESPR2_ACT2_INTERLUDE1@27#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 27
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 4800201
L27_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "PROFESSOR_NPC_NULL_NULL"
L27_1.m_Pos = "R"
L28_1 = "맥크레디 양이 사라졌습니다. 시설에서 원인 불명의 사고가 일어난 모양이더군요."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "マクレディーさんが消えました。施設で原因不明の事故が起きたようです。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Ms. MacCready has gone missing. An unexpected accident occurred at the facility."
L27_1.m_Talk_ENG = L28_1
L28_1 = "麥克蕾蒂不見了。設施裡好像發生了不明原因的事故。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "คุณแมกครีดี้หายตัวไปครับ เกิดเรื่องไม่คาดคิดขึ้นที่ศูนย์"
L27_1.m_Talk_THA = L28_1
L28_1 = "Cô MacCready đã mất tích rồi. Một tai nạn bất ngờ đã xảy ra tại cơ sở."
L27_1.m_Talk_VTN = L28_1
L28_1 = "麦克雷迪不见了。设施里好像发生了不明原因的事故。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Fräulein MacCready ist verschwunden. Offenbar ereignete sich in der Einrichtung ein noch ungeklärter Vorfall."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Mademoiselle MacCready a disparu. Un accident inattendu s'est produit au centre où nous la retenions captive."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "ESPR2_ACT2_INTERLUDE1@28#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 28
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 4800201
L28_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "PROFESSOR_NPC_NULL_NULL"
L28_1.m_Pos = "R"
L29_1 = "학회와 연이 있는 경찰 고위직을 통해 조사를 부탁한 상황입니다."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "学会とつながりがある警察上部を通じて捜査を依頼しました。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "I have asked a police official who has ties to the Society to investigate."
L28_1.m_Talk_ENG = L29_1
L29_1 = "我已經拜託和學會關係不錯的員警高層調查了。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ผมขอให้เจ้าหน้าที่ตำรวจที่ที่เส้นสายกับสมาคมช่วยตรวจสอบแล้ว"
L28_1.m_Talk_THA = L29_1
L29_1 = "Tôi đã nhờ một viên cảnh sát có quan hệ với Hiệp Hội điều tra."
L28_1.m_Talk_VTN = L29_1
L29_1 = "我已经拜托和学会关系不错的警察高层调查了。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Ich habe einen Polizeibeamten, der Verbindungen zur Gesellschaft hat, gebeten, Nachforschungen anzustellen."
L28_1.m_Talk_DEU = L29_1
L29_1 = "J'ai demandé à un officier de police proche de la Société d'enquêter."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "ESPR2_ACT2_INTERLUDE1@29#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 29
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 4800201
