L30_1 = "UNIT_DESPAIR"
L29_1.m_Face = L30_1
L29_1.m_CharStrID = "EDEL_ESPR_NULL_NULL"
L29_1.m_Pos = "L"
L30_1 = "그래요. 레지나 님이……."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "そうですか。レジーナ様が……"
L29_1.m_Talk_JPN = L30_1
L30_1 = "I see. Miss Regina is…"
L29_1.m_Talk_ENG = L30_1
L30_1 = "是嗎，蕾佳娜……"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ดีมากค่ะ ถ้าอย่างนั้นเรจิน่าก็..."
L29_1.m_Talk_THA = L30_1
L30_1 = "Tôi hiểu rồi. Cô Regina…"
L29_1.m_Talk_VTN = L30_1
L30_1 = "是吗，里贾纳……"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Ich verstehe. Regina ist also ..."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Je vois. Regina est donc..."
L29_1.m_Talk_FRA = L30_1
