L31_1 = "ESPR2_ACT2_INTERLUDE1@30#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 30
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 4800201
L30_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "PROFESSOR_NPC_NULL_NULL"
L30_1.m_Pos = "R"
L31_1 = "어떻게 하시겠습니까? 개인적으로는 무척 흥미로운 상황인지라……."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "どうなさいますか？　個人的にはとても興味深い状況ですので……"
L30_1.m_Talk_JPN = L31_1
L31_1 = "What are your future plans? Personally, I find it an intriguing situation..."
L30_1.m_Talk_ENG = L31_1
L31_1 = "你想怎麼辦？我個人覺得這種情況非常有趣……"
L30_1.m_Talk_TWN = L31_1
L31_1 = "คุณมีแผนจะทำยังไงต่อไปครับ ส่วนตัวแล้วผมว่าเรื่องนี้มีลับลมคมใน..."
L30_1.m_Talk_THA = L31_1
L31_1 = "Cô có kế hoạch gì tới đây không? Cá nhân tôi thì thấy đây là một tình huống khá hấp dẫn..."
L30_1.m_Talk_VTN = L31_1
L31_1 = "你想怎么办？我个人觉得这种情况非常有趣……"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Was hast jetzt vor? Ich persönlich finde es eine äußerst faszinierende Situation ..."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Que comptez-vous faire ? Personnellement, je trouve que c'est un déroulement intéressant..."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "ESPR2_ACT2_INTERLUDE1@31#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 31
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 4800201
L31_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_PRIDE"
L31_1.m_CharStrID = "EDEL_ESPR_NULL_NULL"
L31_1.m_Pos = "L"
L32_1 = "괜찮아요. 레지나 님은 분명 제때 돌아오실 테니까."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "大丈夫です。レジーナ様はきっと必要な時にお戻りになりますから。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "It's all right. She will certainly return in time."
L31_1.m_Talk_ENG = L32_1
L32_1 = "沒關係，蕾佳娜到時候一定會回來的。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ไม่เป็นไรค่ะ เรจิน่าจะกลับมาทันเวลาแน่"
L31_1.m_Talk_THA = L32_1
L32_1 = "Không sao mà. Regina chắc chắn sẽ trở lại đúng lúc thôi."
L31_1.m_Talk_VTN = L32_1
L32_1 = "没关系，里贾纳一定会按时回来的。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Schon gut. Sie wird sicherlich rechtzeitig zurückkehren."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Laissons-la agir à sa guise. Je suis sûre qu'elle reviendra bien assez tôt."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "ESPR2_ACT2_INTERLUDE1@32#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 32
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 4800201
L32_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "EDEL_ESPR_NULL_NULL"
L32_1.m_Pos = "L"
L33_1 = "요양이 아주 조금 더 길어질 뿐이랍니다. "
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "療養がほんの少し長引くだけです。 "
L32_1.m_Talk_JPN = L33_1
L33_1 = "However, her recuperation might take longer than expected. "
L32_1.m_Talk_ENG = L33_1
L33_1 = "只是休養時間會延長一點而已。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "แต่ยังไงการพักฟื้นของเธอคงนานกว่าที่คาด"
L32_1.m_Talk_THA = L33_1
L33_1 = "Tuy nhiên, quá trình phục hồi của cô ấy có thể mất nhiều thời gian hơn dự kiến."
L32_1.m_Talk_VTN = L33_1
L33_1 = "只是疗养时间会延长一点而已。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Allerdings könnte ihre Genesung länger dauern als erwartet."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Elle mettra juste plus de temps à récupérer, voilà tout."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "ESPR2_ACT2_INTERLUDE1@33#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 33
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 4800201
L33_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "PROFESSOR_NPC_NULL_NULL"
L33_1.m_Pos = "R"
L34_1 = "흠. 알겠습니다. 그렇게 말씀하신다면야."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "ふむ。わかりました。そうおっしゃるのなら。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Hmm... If you say so, I understand."
L33_1.m_Talk_ENG = L34_1
L34_1 = "嗯，我知道了。既然你這麼說。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "อืม... ถ้าคุณว่าอย่างนั้นผมก็เข้าใจแล้วครับ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Hmm... Nếu cô nói như vậy, tôi hiểu rồi."
L33_1.m_Talk_VTN = L34_1
L34_1 = "嗯，我知道了。既然你这么说。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Hmm. In Ordnung. Wenn du das sagst."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Hmm. Je comprends. Si c'est ce que vous souhaitez..."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "ESPR2_ACT2_INTERLUDE1@34#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 34
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 4800201
L34_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "PROFESSOR_NPC_NULL_NULL"
L34_1.m_Pos = "R"
L35_1 = "생물학부가 악단과 접촉했다더군요. 곧 합류할 겁니다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "生物学部が楽団と接触したそうです。もうすぐ合流するでしょう。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "The Biology Department has made contact with the Orchestra. They will be joining you soon."
L34_1.m_Talk_ENG = L35_1
L35_1 = "生物學院和樂團接觸了。她們應該很快就會加入。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "คณะชีวะติดต่อกับทางวงออเคสตราแล้วนะครับ อีกไม่นานพวกเขาจะมาสมทบ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Ban Sinh Học đã liên lạc với Dàn Nhạc. Họ sẽ sớm tới chỗ cô."
L34_1.m_Talk_VTN = L35_1
L35_1 = "生物学部和乐团接触了。她们应该很快就会加入了。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Die Biologieabteilung hat Kontakt mit dem Orchester aufgenommen. Sie werden bald zu dir stoßen."
L34_1.m_Talk_DEU = L35_1
L35_1 = "La faculté de biologie a pris contact avec l'orchestre. Ils viendront bientôt vous retrouver."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "ESPR2_ACT2_INTERLUDE1@35#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 35
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 4800201
L35_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_Face = "UNIT_LAUGH"
L35_1.m_CharStrID = "EDEL_ESPR_NULL_NULL"
L35_1.m_Pos = "L"
L36_1 = "방해꾼들이 달라붙어서 걱정했는데 다행이네요. 좋은 소식 고마워요."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "邪魔者がくっついているので心配していましたが、安心しました。いい知らせ、ありがとうございます。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "What good news. We were worried about hecklers getting on our back."
L35_1.m_Talk_ENG = L36_1
L36_1 = "那正好，我們本來還擔心會有人來礙事。謝謝你告訴我們這個好消息。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "เป็นข่าวที่ดีมากค่ะ พวกเรากำลังห่วงเลยว่าตัวเกะกะพวกนั้นจะตลบหลังเอา"
L35_1.m_Talk_THA = L36_1
L36_1 = "Tin tốt đấy. Chúng tôi cứ lo mãi về những kẻ phá đám sẽ đâm chọt sau lưng."
L35_1.m_Talk_VTN = L36_1
L36_1 = "那正好，我们本来还担心会有人来碍事。谢谢你告诉我们这个好消息。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Was für eine gute Nachricht. Wir haben uns schon Sorgen gemacht, dass Störenfriede uns auf die Nerven gehen könnten."
L35_1.m_Talk_DEU = L36_1
L36_1 = "C'est une bonne nouvelle. Cela nous aidera à maîtriser les gêneurs."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
