L38_1.m_Face = "UNIT_LAUGH"
L38_1.m_CharStrID = "EDEL_ESPR_SHADOW_NULL"
L38_1.m_Pos = "C"
L39_1 = "외출하는 데 단장하려면 시간이 얼마나 걸릴까요, 세라펠?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "出かけるための支度にどれだけかかりますか？　セラフェル。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "How long will it take for you to get dressed, Serapel?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "想打扮一下出門的話需要多長時間，塞拉費爾？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "เจ้าต้องแต่งตัวนานแค่ไหนเซราเพล?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Serapel, bao giờ cô mới mặc đồ xong?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "你打扮一下出门需要多长时间，塞拉费尔？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Wie lange wird es dauern, bis Sie sich angezogen haben, Serapel?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Combien de temps vous faut-il pour vous habiller, Serapel ?"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "ESPR2_ACT2_INTERLUDE1@39#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 39
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 4800201
L39_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "SERAPEL_QLIPHOTH_NULL_NULL"
L39_1.m_Pos = "C"
L40_1 = "글쎄. 속삭이는 자가 언제 클리포트 게임을 선포하느냐에 따라 달렸지."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "そうね。囁く者がいつクリフォトゲームを宣布するかによるわ。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Hmm... Depends on when the Whisperer declares the start of the Qliphoth Game."
L39_1.m_Talk_ENG = L40_1
L40_1 = "這個嘛，取決於低語者什麼時候宣佈逆卡巴拉遊戲開始。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "อืม... ก็แล้วแต่ว่าผู้กระซิบจะประกาศเริ่มคลิฟอธเกมตอนไหนนะ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Hmm... Tùy thuộc vào thời điểm Kẻ Thì Thầm tuyên bố bắt đầu Trò Chơi Qliphoth."
L39_1.m_Talk_VTN = L40_1
L40_1 = "这个嘛，取决于低语者什么时候宣布神圣战役开始。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Hmm. Es hängt davon ab, wann der Flüsterer den Beginn des Klippot-Handstreichs ankündigt."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Hmm... tout dépend de quand le Murmureur décidera d'ouvrir le Jeu de Qliphoth."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "ESPR2_ACT2_INTERLUDE1@40#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 40
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 4800201
L40_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
