L40_1.m_Pos = "C"
L41_1 = "m_Crash"
L40_1[L41_1] = 20
L41_1 = "아아, 기대되는 순간이군. 오랜만에 아주……."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "ああ、その瞬間が楽しみだわ。久々にとても……"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Aah... I've been eagerly awaiting this moment for so long..."
L40_1.m_Talk_ENG = L41_1
L41_1 = "啊啊，好期待那一刻啊，應該可以體驗……"
L40_1.m_Talk_TWN = L41_1
L41_1 = "อาห์... ข้ารอช่วงเวลานี้มานานแสนนานแล้ว"
L40_1.m_Talk_THA = L41_1
L41_1 = "Aah... Tôi đã háo hức chờ đợi khoảnh khắc này quá lâu rồi..."
L40_1.m_Talk_VTN = L41_1
L41_1 = "啊啊，好期待……那一刻，我就可以亲身体验……"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Ahh ... Ich habe diesen Moment schon so lange sehnsüchtig erwartet ..."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Ah... j'attends ce moment depuis si longtemps."
L40_1.m_Talk_FRA = L41_1
