L42_1 = "아주 고통스러운 시간이 되겠어."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "とても苦しい時間になりそう。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "It will be a time of great suffering."
L41_1.m_Talk_ENG = L42_1
L42_1 = "久違的痛苦吧。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "มันจะเป็นช่วงเวลาแห่งมหาทุกข์ทรมานแน่"
L41_1.m_Talk_THA = L42_1
L42_1 = "Đó sẽ là khoảng thời gian đau khổ tuyệt vời."
L41_1.m_Talk_VTN = L42_1
L42_1 = "那久违的痛苦。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Es wird eine sehr schmerzhafte Zeit."
L41_1.m_Talk_DEU = L42_1
L42_1 = "L'évènement promet de me donner de délicieuses souffrances."
L41_1.m_Talk_FRA = L42_1
