L46_1 = "ESPR2_ACT2_INTERLUDE1@45#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 45
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 4800201
L45_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "DRIVER_NPC_ALPHA_NULL"
L45_1.m_CharStrID = L46_1
L46_1 = "마침 주유소가 있군. 여기서 잠시 쉬어가지."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "ちょうどガソリンスタンドがあるな。ここでしばらく休憩しよう。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "There is a gas station ahead. Let's take a break there."
L45_1.m_Talk_ENG = L46_1
L46_1 = "正好有個加油站，在這裡休息一下吧。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "มีปั๊มน้ำมันข้างหน้านะ พักกันหน่อยดีกว่า"
L45_1.m_Talk_THA = L46_1
L46_1 = "Có một trạm xăng phía trước. Chúng ta hãy nghỉ tạm ở đó."
L45_1.m_Talk_VTN = L46_1
L46_1 = "正好有个加油站，在这里休息一下吧。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Vor uns ist eine Tankstelle. Machen wir dort eine Pause."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Ah, une station-service. Profitons-en pour faire une pause."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "ESPR2_ACT2_INTERLUDE1@46#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 46
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 4800201
L46_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "DRIVER_NPC_ALPHA_NULL"
L46_1.m_CharStrID = L47_1
L47_1 = "다들 내려, 아가씨들. 갈길이 머니 얼른 볼일 보러 갔다 오라고."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "下りてくれ、お嬢ちゃんたち。先は長いんだ、急いで用を足して帰ってきてくれ。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Get out, ladies. We have a long road ahead of us, so go get your business done quick."
L46_1.m_Talk_ENG = L47_1
L47_1 = "快下車，小姐們。路途遙遠，都快去方便一下吧。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ลงไปซะสาวๆ หนทางยังอีกยาวไกล ไปทำธุระกันซะให้ไวๆ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Ra ngoài đi, các quý cô. Chúng ta còn một chặng đường dài phía trước, vì vậy nhanh lên nhé."
L46_1.m_Talk_VTN = L47_1
L47_1 = "快下车，小姐们。路途遥远，都快去方便一下吧。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Aussteigen, meine Damen. Wir haben noch einen langen Weg vor uns, also erledigt schnell eure Besorgungen."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Descendez, mesdames. La route est encore longue, c'est le moment d'aller vous alléger."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "ESPR2_ACT2_INTERLUDE1@47#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 47
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 4800201
L47_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "DRIVER_NPC_ALPHA_NULL"
L47_1.m_CharStrID = L48_1
L48_1 = "이런 허허벌판 한가운데에서 가 봤자 어디로 가겠냐마는. 흐흐흐……."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "こんな荒野のど真ん中じゃ、行くっていってもどこにも行くところはないだろうけどな。ふふふ……"
L47_1.m_Talk_JPN = L48_1
L48_1 = "But then again, where can you ladies go in the middle of nowhere... Kekeke..."
L47_1.m_Talk_ENG = L48_1
L48_1 = "就是不知道在這種空曠的原野中能去哪裡，呵呵呵……"
L47_1.m_Talk_TWN = L48_1
L48_1 = "แต่พูดก็พูดเถอะ สาวๆ อย่างพวกเธอมาโผล่กลางที่แบบนี้กันได้ยังไงเนี่ย... อิอิอิ..."
L47_1.m_Talk_THA = L48_1
L48_1 = "Nhưng, các quý cô đây sao lại lang thang khắp nơi thế... Kekeke..."
L47_1.m_Talk_VTN = L48_1
L48_1 = "就是不知道在这种空旷的原野中能去哪里，咦嘻嘻嘻……"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Aber andererseits, wo könntet ihr Damen hier mitten im Nirgendwo überhaupt hingehen? Hehehe ..."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Enfin pour des femmes, je suppose que vous n'avez pas vraiment où aller pour vous décharger. Hé hé..."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
