L51_1 = "CUTSCENE_TALK_01"
L50_1.m_StartBGMFileName = L51_1
L51_1 = "SILKY_NPC_ESPR2_NULL"
L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "L"
L51_1 = "말 없이 움직이는 마차를 직접 타 보다니……. 꿈만 같아요."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "馬なしで走る馬車に乗ることになるなんて……夢みたいです。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "It's my first time riding a carriage without a horse... It's like I'm in a dream...!"
L50_1.m_Talk_ENG = L51_1
L51_1 = "我竟然坐上了沒有馬也能跑的馬車……好像做夢一樣。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "เกิดมาฉันก็เพิ่งเคยนั่งเกวียนที่ไม่มีม้านี่แหละค่ะ... อย่างกับฝันไปเลย...!"
L50_1.m_Talk_THA = L51_1
L51_1 = "Đây là lần đầu tiên tôi đi xe ngựa mà không có ngựa... Cứ như tôi đang mơ ấy...!"
L50_1.m_Talk_VTN = L51_1
L51_1 = "我竟然坐上了没有马也能跑的马车……好像做梦一样。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Es ist das erste Mal, dass ich mit einer Kutsche ohne Pferd fahre ... Es fühlt sich wie ein Traum an!"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Une calèche sans cheval... quel prodige ! J'ai l'impression d'être dans un rêve."
L50_1.m_Talk_FRA = L51_1
