L2_1 = "ESPR2_ACT2_INTERLUDE1@51#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 51
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 4800201
L1_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "REGINA_ESPR_NULL_NULL"
L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "R"
L2_1 = "m_Crash"
L1_1[L2_1] = 10
L2_1 = "으으, 트럭 짐칸은 사람 탈 곳이 못 되네요. 이러다 엉덩이가 쪼개지겠어요."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "うう、トラックの荷台は人が乗るところではありませんね。このままではお尻が割れてしまいますわ。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Ngh... The truck bed is no place for passengers. I feel I might bruise my buttocks!"
L1_1.m_Talk_ENG = L2_1
L2_1 = "呃呃，卡車的車廂真不是人待的地方。我的屁股好痛。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "อึก... กระบะรถนี่ไม่ใช่ที่ของผู้โดยสารสักนิด ก้นฉันระบมไปหมดแล้วเนี่ย!"
L1_1.m_Talk_THA = L2_1
L2_1 = "Ngh... Xe giường nằm hết sạch chỗ. Tôi cảm tưởng như mông mình đang sưng bầm lên ấy!"
L1_1.m_Talk_VTN = L2_1
L2_1 = "呃呃，卡车的车厢真不是人待的地方。我的屁股疼死了。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Urgh. Die Ladefläche eines Lastwagens ist eigentlich kein Ort zum Mitfahren. Wenn das so weitergeht, wird mein Hintern sich noch spalten."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Ngh... le lit de ce camion n'est pas fait pour les humains, c'est pas possible ! J'ai l'impression que mon dos va se casser."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "ESPR2_ACT2_INTERLUDE1@52#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 52
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 4800201
L2_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_Face = "UNIT_SURPRISE"
L3_1 = "SILKY_NPC_ESPR2_NULL"
L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "L"
L3_1 = "m_Crash"
L2_1[L3_1] = 15
L3_1 = "앗, 그런 문제는 제게 맡겨 주세요."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "あっ、それでしたらお任せください。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Oh! If you're feeling uncomfortable, leave it to me."
L2_1.m_Talk_ENG = L3_1
L3_1 = "啊，這個問題交給我吧。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "อ้อ! ถ้าคุณไม่ค่อยสบาย เดี๋ยวฉันจัดการให้ค่ะ"
L2_1.m_Talk_THA = L3_1
L3_1 = "Ồ! Nếu cô cảm thấy không thoải mái, để đó cho tôi đi."
L2_1.m_Talk_VTN = L3_1
L3_1 = "啊，这个问题交给我吧。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Oh! Bitte überlassen Sie dieses Problem mir."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Ah, laissez-moi faire !"
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "ESPR2_ACT2_INTERLUDE1@53#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 53
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 4800201
L3_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_LAUGH"
L4_1 = "SILKY_NPC_ESPR2_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "L"
L4_1 = "제가 엎드려서 부학회장님의 방석이라도 되어 드릴게요. 간병인이니까요."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "私が伏せて副学会長様のクッションにでもなります。看病人ですから。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "I'll lie down and become your cushion. I am your caregiver after all."
L3_1.m_Talk_ENG = L4_1
L4_1 = "我可以躺下給副學會長當坐墊，因為我是你的看護。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "เดี๋ยวฉันนอนเป็นเบาะให้นะคะรองประธาน ยังไงฉันก็เป็นผู้ดูแลคุณอยู่แล้ว"
L3_1.m_Talk_THA = L4_1
L4_1 = "Tôi sẽ nằm xuống và trở thành đệm của cô, Phó Chủ Tịch. Dù sao tôi cũng là người chăm sóc cô."
L3_1.m_Talk_VTN = L4_1
L4_1 = "我可以躺下给副会长当坐垫，因为我是你的护工嘛。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Ich werde mich hinlegen und Ihr Kissen sein. Schließlich bin ich Ihre Betreuerin, stellvertretende Gesellschaftsvorsitzende."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Je vais m'allonger en dessous pour vous servir de coussin. C'est mon rôle de vous aider à reprendre des forces, après tout."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "ESPR2_ACT2_INTERLUDE1@54#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 54
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 4800201
L4_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "UNIT_SERIOUS"
L4_1.m_Face = L5_1
L5_1 = "REGINA_ESPR_NULL_NULL"
L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "R"
L5_1 = "아, 아뇨. 그러지 말아 주세요. 제가 더 부담스럽습니다."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "い、いいえ。それはやめてください。かえって落ち着きませんわ。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "N-no, thank you. That won't be necessary."
L4_1.m_Talk_ENG = L5_1
L5_1 = "不…不用，千萬別那麼做。那樣我會有壓力的。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "มะ-ไม่เป็นไร ขอบคุณนะ ไม่ต้องหรอก"
L4_1.m_Talk_THA = L5_1
L5_1 = "K-không, cảm ơn. Không cần thiết đâu."
L4_1.m_Talk_VTN = L5_1
L5_1 = "不、不用，千万别那么做。那样我会有负担的。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "N-nein, danke. Das ist doch nicht nötig. Außerdem wäre mir das äußerst unangenehm."
L4_1.m_Talk_DEU = L5_1
L5_1 = "N-Nn, merci. Ce ne sera pas nécessaire."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
