L7_1 = "ESPR2_ACT2_INTERLUDE1@56#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 56
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 4800201
L6_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "USER_ADMIN_NULL_NULL"
L6_1.m_CharStrID = L7_1
L7_1 = "하지만 얄궂은 상황이군. 맥크레디 집안 사람이 트럭 짐칸을 얻어 타야 하다니."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "しかし、妙な状況だな。マクレディー家の人間がトラックの荷台に乗せてもらわなくてはならないとは。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "What an ironic situation. A MacCready riding in the back of a truck."
L6_1.m_Talk_ENG = L7_1
L7_1 = "不過真是不可思議啊。麥克蕾蒂家族的人居然要搭順風車，而且還是坐在卡車車廂裡。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ย้อนแย้งอะไรแบบนี้นี่ คนบ้านแมกครีดี้ต้องมานั่งอยู่หลังกระบะรถ"
L6_1.m_Talk_THA = L7_1
L7_1 = "Thật là một tình huống trớ trêu. Một người nhà MacCready ngồi sau xe tải."
L6_1.m_Talk_VTN = L7_1
L7_1 = "真是不可思议啊。麦克雷迪家族的成员居然沦落到了搭顺风车的地步，而且还是坐在卡车车厢里。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Was für eine ironische Situation. Eine MacCready, die auf der Ladefläche eines Lastwagens mitfährt."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Une MacCready à l'arrière d'un camion... quel spectacle ironique !"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
