L9_1 = "ESPR2_ACT2_INTERLUDE1@58#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 58
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 4800201
L8_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "REGINA_ESPR_NULL_NULL"
L8_1.m_CharStrID = L9_1
L8_1.m_Pos = "C"
L9_1 = "불행 중 다행이죠. 히치하이킹에 실패했으면 아직도 황무지를 걷고 있었을 테니까요."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "不幸中の幸いというべきでしょう。ヒッチハイクに失敗していたら、まだ荒れ地を歩いていたはずですから。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Lucky it was not worse. We would be walking across this wasteland if we had failed to hitch a ride."
L8_1.m_Talk_ENG = L9_1
L9_1 = "這是不幸中的大幸。搭順風車失敗的話，我們現在應該還在荒郊野外走路呢。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ก็ยังดีที่ไม่แย่กว่านี้นะ ถ้าโบกรถไม่ได้คงได้เดินข้ามทุ่งร้างกันแน่"
L8_1.m_Talk_THA = L9_1
L9_1 = "Có còn hơn không. Đáng lẽ chúng ta phải cuốc bộ qua vùng hoang địa này nếu không bắt gặp chiếc xe."
L8_1.m_Talk_VTN = L9_1
L9_1 = "这是不幸中的万幸。搭顺风车失败的话，我们现在应该还在大荒地上徒步呢。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Wir haben Glück im Unglück. Wenn wir es nicht geschafft hätten, per Anhalter zu fahren, würden wir immer noch durch dieses Ödland irren."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Ça pourrait être pire. Au moins avec ça, on peut traverser ce désert."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "ESPR2_ACT2_INTERLUDE1@59#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 59
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 4800201
L9_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "REGINA_ESPR_NULL_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L10_1 = "그리고 사장님도 날지 못해서 제 어깨를 빌린 처지 아닌가요? 피차일반인 셈이죠."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "それに、社長も飛べずに私の肩を借りている身ではないですか。お互い様ですわ。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Likewise, you are borrowing my shoulder because you can't fly. So are you not in the same situation as us?"
L9_1.m_Talk_ENG = L10_1
L10_1 = "還有，老闆也是不能飛，才借用我的肩膀吧？大家處境相同不是嗎。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "แล้วก็เหมือนกันแหละ คุณก็บินไม่ได้เลยต้องยืมไหล่ฉัน เราก็สภาพเดียวกันไม่ใช่รึไง?"
L9_1.m_Talk_THA = L10_1
L10_1 = "Nói như thế thì Ông Chủ đang mượn bờ vai của tôi vì không thể bay. Vậy chẳng phải Ông Chủ cũng đang ở trong tình huống giống chúng tôi sao?"
L9_1.m_Talk_VTN = L10_1
L10_1 = "还有，老板也是不能飞，才借用我的肩膀吧？大家处境相同不是吗。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Und Sie leihen sich meine Schulter aus, weil Sie nicht fliegen können. Also befinden Sie sich in derselben Situation wie wir, Boss."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Et puis je vous signale que vous êtes sur mon épaule parce que vous ne pouvez pas voler. Vous n'êtes pas vraiment bien placé pour parler, si ?"
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
