L12_1 = "ESPR2_ACT2_INTERLUDE1@61#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 61
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 4800201
L11_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "USER_ADMIN_NULL_NULL"
L11_1.m_CharStrID = L12_1
L12_1 = "하하, 이거 정곡을 찔렸군."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "はは、これは痛いところを突かれたな。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Haha. Rubbing salt in my wounds, eh?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "哈哈，你說這話真是命中要害。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ฮ่าฮ่า ไปทางขยี้กันซะแล้วเหรอเนี่ย?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Haha. Định sát muối vào vết thương của tôi sao?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "呃哈哈，你这话说得在理，是我的错。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Haha. Du hast den Nagel auf den Kopf getroffen."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Ha ha, tu sais retourner le couteau dans la plaie."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "ESPR2_ACT2_INTERLUDE1@62#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 62
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 4800201
L12_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "UNIT_DESPAIR"
L12_1.m_Face = L13_1
L13_1 = "REGINA_ESPR_NULL_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "조금은 화를 내시라고요. 발끈한 저만 좀스러운 것 같잖아요."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "少しは怒ってください。かっとなった私だけ器が小さい人みたいではないですか。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "I want you to get a little angry. I seem petty if I am the only one fuming."
L12_1.m_Talk_ENG = L13_1
L13_1 = "你也可以發火啊。只有我一個人生氣的話，顯得我多小氣。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ฉันอยากให้คุณโกรธสักนิดนะ กรุ่นอยู่คนเดียวแบบนี้มันน่าสมเพชจัง"
L12_1.m_Talk_THA = L13_1
L13_1 = "Tôi muốn cho Ông Chủ biết thế nào là giận dỗi. Thật nhỏ mọn nếu chỉ mình tôi là người đang bực."
L12_1.m_Talk_VTN = L13_1
L13_1 = "你也可以发火啊。只有我一个人耍性子的话，显得我多小气。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Ich möchte, dass Sie auch ein wenig wütend werden. Ich wirke kleinlich, wenn ich die Einzige bin, die wütend ist."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Vous ne voulez pas vous énerver, un peu ? Si je suis la seule à fulminer, cela ressemble à un caprice."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
