L16_1 = "ESPR2_ACT2_INTERLUDE1@65#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 65
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 4800201
L15_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "REGINA_ESPR_NULL_NULL"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "L"
L16_1 = "루나, 수도원까지는 얼마나 더 가야 하죠?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "ルナさん、修道院まではあとどれほどかかりますか？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Luna, how much farther until we arrive at the monastery?"
L15_1.m_Talk_ENG = L16_1
L16_1 = "露娜，還要走多久才能到修道院？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ลูน่า อีกไกลแค่ไหนจะถึงอารามน่ะ?"
L15_1.m_Talk_THA = L16_1
L16_1 = "Luna, còn bao xa nữa thì chúng ta mới tới tu viện?"
L15_1.m_Talk_VTN = L16_1
L16_1 = "露娜，还要走多久才能到修道院？"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Luna, wie weit müssen wir noch bis zum Kloster gehen?"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Luna, le monastère est encore loin ?"
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "ESPR2_ACT2_INTERLUDE1@66#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 66
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 4800201
L16_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "TRUMPET_HARMONY_ESPR2_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "R"
L16_1.m_bCharPinup = true
L17_1 = 0.25
L16_1.m_bCharPinupEasingTime = L17_1
L17_1 = "말 걸지 마…. 날지 못하니까 멀미 때문에 죽겠어…."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "話しかけないで……飛べないし、車酔いのせいで死にそうなんだから……"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Don't talk to me... I'm getting carsick..."
L16_1.m_Talk_ENG = L17_1
L17_1 = "別跟我說話……因為不能飛，我現在很暈……"
L16_1.m_Talk_TWN = L17_1
L17_1 = "อย่ามาชวนคุยนะ... ฉันเมารถอยู่..."
L16_1.m_Talk_THA = L17_1
L17_1 = "Đừng có nói chuyện với tôi... Tôi đang bị say xe..."
L16_1.m_Talk_VTN = L17_1
L17_1 = "别跟我说话……我，我好像晕车了……"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Sprich mich nicht an ... Da ich nicht fliegen kann, werde ich wohl oder übel an einer Reisekrankheit sterben ..."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Laisse-moi tranquille... je crois que je vais vomir..."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "ESPR2_ACT2_INTERLUDE1@67#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 67
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 4800201
L17_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_SURPRISE"
L18_1 = "REGINA_ESPR_NULL_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "L"
L18_1 = "m_Crash"
L19_1 = 30
L17_1[L18_1] = L19_1
L18_1 = "몸이 잿가루가 돼서 날리고 있잖아요! 어서 내려서 바람 좀 쐐요!"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "体が灰になって飛ばされているではないですか！　早く降りて風に当たりなさい！"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Your body is flaking into ashes! Get out and get some fresh air!"
L17_1.m_Talk_ENG = L18_1
L18_1 = "你的身體好多灰塵！快點下來呼吸點新鮮空氣吧！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ตัวเธอร่อนเป็นผงแล้วเนี่ย! ออกไปสูดอากาศบริสุทธิ์ไป๊!"
L17_1.m_Talk_THA = L18_1
L18_1 = "Cơ thể của cô đang tan ra thành tro đấy! Ra ngoài và hít thở không khí trong lành đi nào!"
L17_1.m_Talk_VTN = L18_1
L18_1 = "你的身体好多灰尘！快点下来呼吸点新鲜空气吧！"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Dein Körper verwandelt sich in Asche und weht davon! Steig aus und schnapp etwas frische Luft!"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Votre corps est en train d'être réduit en cendres ! Allez prendre un peu l'air, enfin !"
L17_1.m_Talk_FRA = L18_1
