L21_1.m_Face = "UNIT_SURPRISE"
L22_1 = "TRUMPET_HARMONY_ESPR2_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "R"
L22_1 = "후아, 이제 좀 살겠다. 생각보다 회복에 힘을 너무 많이 썼나 봐."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "ふわ～生き返る。思ったより回復に力を使い過ぎてたみたい。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Huah! That's so much better. Maybe I used up too much of my power recovering..."
L21_1.m_Talk_ENG = L22_1
L22_1 = "呼，總算活過來了。看來想要恢復狀態，比我預期得更耗體力。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "อะเหื้อ! ดีขึ้นเยอะเลยแฮะ สงสัยฉันจะใช้พลังฟื้นตัวมากไปหน่อย..."
L21_1.m_Talk_THA = L22_1
L22_1 = "Huah! Thoải mái quá. Có lẽ tôi đã sử dụng quá nhiều năng lượng hồi phục..."
L21_1.m_Talk_VTN = L22_1
L22_1 = "总算活过来了！看来想要恢复状态，比我预想的更耗能量。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Puh! Endlich geht es mir besser. Vielleicht habe ich bei der Regenerierung meines Körpers zu viel von meiner Kraft verbraucht ..."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Pouah, ça fait du bien ! Je crois bien que j'ai un peu trop forcé tout à l'heure..."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "ESPR2_ACT2_INTERLUDE1@72#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 72
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 4800201
L22_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_Face = "UNIT_HATE"
L23_1 = "TRUMPET_HARMONY_ESPR2_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "R"
L23_1 = "m_Crash"
L22_1[L23_1] = 15
L23_1 = "그 괴물 녀석, 또 나타나면 셰나한테 혼내 달라고 해야지! 다음에 나타나기만 해!"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "あの怪物め、また現れたらシェナにとっちめてもらう！　覚えてろよ！"
L22_1.m_Talk_JPN = L23_1
L23_1 = "That monster... I'm going to tell Shena to rip it a new one the next time I see it!"
L22_1.m_Talk_ENG = L23_1
L23_1 = "如果那個怪物再出現的話，我一定要讓世娜好好教訓它！看它敢不敢再出現！"
L22_1.m_Talk_TWN = L23_1
L23_1 = "สัตว์ประหลาดนั่น... คราวหน้าฉันจะบอกให้ชีน่าฉีกทิ้งจนมันจำหน้าตัวเองไม่ได้เลยคอยดู!"
L22_1.m_Talk_THA = L23_1
L23_1 = "Con quái vật đó... Tôi sẽ bảo Shena xé xác nó nếu còn gặp nó lần nữa!"
L22_1.m_Talk_VTN = L23_1
L23_1 = "呸！呸！如果那个怪物再来的话，我一定要让赛娜好好教训它！看它敢不敢再出现！"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Wenn dieses Monster wieder auftaucht, soll Shena ihm eine ordentliche Standpauke halten!"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Ce monstre... la prochaine fois qu'il se pointe, je demanderai à Shena de lui régler son compte !"
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "ESPR2_ACT2_INTERLUDE1@73#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 73
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 4800201
L23_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "SILKY_NPC_ESPR2_NULL"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "L"
L24_1 = "셰나란 분은 굉장히 힘이 세신가 봐요."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "シェナという方はとてもお強い方のようですね。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "This Shena person must be really strong."
L23_1.m_Talk_ENG = L24_1
L24_1 = "看來那個叫世娜的人很厲害。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "คนที่ชื่อชีน่านี่คงเก่งมากเลยนะคะ"
L23_1.m_Talk_THA = L24_1
L24_1 = "Hẳn là cái người Shena này phải mạnh lắm."
L23_1.m_Talk_VTN = L24_1
L24_1 = "看来那个叫赛娜的人很厉害。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Diese Shena muss wirklich stark sein."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Cette Shena doit vraiment être forte !"
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "ESPR2_ACT2_INTERLUDE1@74#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 74
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 4800201
L24_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_IDLE"
L25_1 = "TRUMPET_HARMONY_ESPR2_NULL"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "R"
L25_1 = "그럼. 평소엔 웃고 다녀도 화나면 얼마나 무서운데."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "もちろん。普段は笑っていても怒るとものすごく怖いんだから。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Yup! She may always smile, but if you irritate her, she'll be the scariest person you'll ever meet."
L24_1.m_Talk_ENG = L25_1
L25_1 = "那當然。平時笑的時候就很嚇人，生氣的話會更加可怕。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ใช่! เธอยิ้มตลอดเวลาแหละ แต่ถ้าไปทำเสียเส้นเข้าละก็ จะกลายเป็นคนที่น่ากลัวที่สุดที่เคยเจอเลย"
L24_1.m_Talk_THA = L25_1
L25_1 = "Yup! Cô ấy có thể luôn mỉm cười, nhưng nếu bị chọc tức, cô ấy sẽ là người đáng sợ nhất mà cô từng gặp."
L24_1.m_Talk_VTN = L25_1
L25_1 = "那当然。平时笑的时候就很吓人，生气的话会更加可怕。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Oh ja! Sie mag zwar immer ein Lächeln im Gesicht haben, aber wenn man sie mal verärgert hat, wirkt sie unglaublich angsteinflößend."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Ouais ! Elle a toujours le sourire aux lèvres, mais vaut mieux pas la chercher."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "ESPR2_ACT2_INTERLUDE1@75#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 75
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 4800201
L25_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_HATE"
L26_1 = "TRUMPET_HARMONY_ESPR2_NULL"
L25_1.m_CharStrID = L26_1
L25_1.m_Pos = "R"
L26_1 = "m_Crash"
L25_1[L26_1] = 15
L26_1 = "그 녀석, 셰나 앞에 서면 꼼짝도 못 할 걸? 퓩퓩 찔려서 걸레짝이나 되라지!"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "あいつ、シェナの前では動けもしないよ！　ブスブス刺されてボロボロになっちゃえ！"
L25_1.m_Talk_JPN = L26_1
L26_1 = "I bet it won't even be a match against Shena. She'll stab it and turn it to rags in mere seconds!"
L25_1.m_Talk_ENG = L26_1
L26_1 = "那傢伙，站在世娜面前估計動都動不了？肯定會被撕爛！"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ฉันมั่นใจเลยนะว่ามันไม่พอมือชีน่าหรอก ไม่กี่วิเธอก็แทงมันยุ่ยเป็นผ้าขี้ริ้วแล้ว!"
L25_1.m_Talk_THA = L26_1
L26_1 = "Tôi cá là chuyện đó thậm chí còn chẳng phải là một trận so găng với Shena. Cô ấy sẽ đâm nó và biến nó thành rác rưởi chỉ trong vài giây!"
L25_1.m_Talk_VTN = L26_1
L26_1 = "那家伙，站在赛娜面前估计动都动不了？肯定会被唰唰刺破，变成破抹布！"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Ich wette, dieses Ding hätte keine Chance gegen Shena. Sie würde es so heftig aufschlitzen, dass es nur noch ein Lumpen wäre!"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Ce monstre aura même pas le temps d'attaquer qu'elle l'aura tranché, tailladé, découpé, évidé ! Ça lui apprendra."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
