L29_1 = "ESPR2_ACT2_INTERLUDE1@78#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 78
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 4800201
L28_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_Face = "UNIT_IDLE"
L29_1 = "REGINA_ESPR_NULL_NULL"
L28_1.m_CharStrID = L29_1
L29_1 = "L_M_I"
L28_1.m_Pos = L29_1
L29_1 = "대체 그 괴물에게 얼마나 심하게 당했는데 그래요?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "いったいあの怪物にどれほど酷くやられたのですか？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "How badly were you injured by it anyway?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "你到底和那個怪物有什麼深仇大恨？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ว่าแต่เธอบาดเจ็บหนักขนาดไหนนี่?"
L28_1.m_Talk_THA = L29_1
L29_1 = "Thế nó làm cô bị thương nặng đến thế nào?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "你到底和那个怪物有多大仇啊？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Wie schwer wurdest du überhaupt von diesem Monster verletzt?"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Ce monstre vous a vraiment énervée, hein ?"
L28_1.m_Talk_FRA = L29_1
