L30_1 = "ESPR2_ACT2_INTERLUDE1@79#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 4800201
L29_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "TRUMPET_HARMONY_ESPR2_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "R"
L30_1 = "허리가 동강나 버렸어."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "体が真っ二つになったんだ。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "It cut me in half by the waist."
L29_1.m_Talk_ENG = L30_1
L30_1 = "我被它劈成兩半。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "มันฟันเอวฉันตัวขาดสองท่อนเลยน่ะ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Nó cắt đôi tôi ra ở phần eo."
L29_1.m_Talk_VTN = L30_1
L30_1 = "我被它拦腰斩断了。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Es hat mich an der Taille in zwei Hälften geschnitten."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Il m'a coupée en deux. Littéralement."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "ESPR2_ACT2_INTERLUDE1@80#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 80
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 4800201
L30_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_Face = "UNIT_SURPRISE"
L31_1 = "REGINA_ESPR_NULL_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "L"
L31_1 = "허리가요? 그러고도 살아 있다고요?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "体がですか？　それでも生きていられるんですの？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "The waist?! And you are still alive?!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "劈成兩半？那你為什麼還活著？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เอวเหรอ?! แล้วยังไม่ตายได้ไงก่อน?!"
L30_1.m_Talk_THA = L31_1
L31_1 = "Ở eo?! Và cô vẫn còn sống ư?!"
L30_1.m_Talk_VTN = L31_1
L31_1 = "拦腰斩断？可你为什么还活着？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "An der Taille?! Und du lebst noch?!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Coupée en deux ? Et vous êtes encore en vie ?"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "ESPR2_ACT2_INTERLUDE1@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 4800201
L31_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_PRIDE"
L32_1 = "TRUMPET_HARMONY_ESPR2_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "R"
L32_1 = "흐흥. 어때, 놀랐냐? 괜히 오래된 그림자가 아니라구."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "ふふ～ん。どう、驚いた？　シャドウとして伊達に長く生きてないっての。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Hehe. Surprised? That's nothing for a ancient Shadow like me."
L31_1.m_Talk_ENG = L32_1
L32_1 = "呵呵，怎麼樣，嚇到了？作為古老的暗影，我可不是白活的。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ฮี่ฮี่ แปลกใจปะล่า? แค่นี้แชโดว์ไม่เป็นไรหรอก"
L31_1.m_Talk_THA = L32_1
L32_1 = "Hehe. Ngạc nhiên lắm hả? Chuyện đó không là gì đối với một Cái Bóng."
L31_1.m_Talk_VTN = L32_1
L32_1 = "呵呵，怎么样，吓到了？作为古老的暗影，我可不是白活的。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Hehe. Was bist du denn so überrascht? Das ist doch nichts für einen uralten Schatten wie mich."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Hé hé. Surprise ? Pour une Ombre aussi âgée que moi, c'est rien du tout !"
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
