L33_1 = "REGINA_ESPR_NULL_NULL"
L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "L"
L33_1 = "네. 놀랐습니다. 단세포 동물도 그림자가 될 수 있었군요."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "はい。驚きました。単細胞生物もシャドウになれるのですね。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Yes. I am surprised to learn that even someone like you can even become a Shadow."
L32_1.m_Talk_ENG = L33_1
L33_1 = "是啊，嚇到我了。原來單細胞生物，也能成為暗影啊。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "แน่สิ ฉันแปลกใจนะที่ได้รู้ว่าคนแบบเธอก็กลายเป็นแชโดว์ได้ด้วย"
L32_1.m_Talk_THA = L33_1
L33_1 = "Đúng. Tôi ngạc nhiên khi biết rằng ngay cả một người như cô cũng có thể trở thành Cái Bóng.."
L32_1.m_Talk_VTN = L33_1
L33_1 = "是啊，吓到我了。原来单细胞生物，也能成为暗影啊。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Ja. Ich bin überrascht zu erfahren, dass sogar jemand wie du ein Schatten werden kann."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Oui. Je suis surprise d'apprendre que même les créatures unicellulaires comme vous peuvent devenir des Ombres."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "ESPR2_ACT2_INTERLUDE1@83#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 4800201
L33_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
