L34_1 = "UNIT_SERIOUS"
L33_1.m_Face = L34_1
L34_1 = "TRUMPET_HARMONY_ESPR2_NULL"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "R"
L34_1 = "누구더러 단세포래? 너 진짜……"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "誰が単細胞だよ！　あんたね……"
L33_1.m_Talk_JPN = L34_1
L34_1 = "What do you mean \"someone like me\"?! Sheesh–"
L33_1.m_Talk_ENG = L34_1
L34_1 = "你說誰單細胞呢？真是的……"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ไอ้ \"คนแบบเธอ\"?! นี่มันหมายความว่าไงนะ ชรรรรรรริส์–"
L33_1.m_Talk_THA = L34_1
L34_1 = "Cô nói \"một người như tôi\" là sao?! Xí-"
L33_1.m_Talk_VTN = L34_1
L34_1 = "你说谁单细胞呢？真是的……"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Was meinst du mit \"jemand wie du\"?! Du fiese ..."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Unicellulaire ? Non mais qu'est-ce que..."
L33_1.m_Talk_FRA = L34_1
