L36_1 = "…잠깐 휴전. 밥부터 먹자."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "……ちょっと休戦。まず食事をしよう。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "W-wait. I call truce. I need to eat first"
L35_1.m_Talk_ENG = L36_1
L36_1 = "……暫時休戰，先去吃飯吧。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ดะ-เดี๋ยว ขอสงบศึก ฉันต้องหาอะไรกินก่อนละ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Đ-đợi đã. Tạm dừng đi. Tôi cần ăn gì đó đã"
L35_1.m_Talk_VTN = L36_1
L36_1 = "……暂时休战，先去吃饭吧。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "... Moment. Kurzer Waffenstillstand! Lass uns zuerst etwas essen."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Stop. Avant tout, il faut que je mange quelque chose."
L35_1.m_Talk_FRA = L36_1
