L37_1[L38_1] = L39_1
L38_1 = "난 햄버거! 싱싱한 토마토랑 아삭아삭한 양상추, 거기에 두툼한 패티까지~"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "アタシはハンバーガー！　新鮮なトマトにシャキシャキのレタス、それに分厚いパテをのせて～"
L37_1.m_Talk_JPN = L38_1
L38_1 = "I want a burger! With some fresh tomatoes and crunchy lettuce, and a juicy patty on top!"
L37_1.m_Talk_ENG = L38_1
L38_1 = "我要吃漢堡！新鮮的番茄，清脆的生菜，再加上厚厚的肉排～"
L37_1.m_Talk_TWN = L38_1
L38_1 = "อยากกินเบอร์เกอร์อะ! แบบมีมะเขือเทศกับผักกาดกรอบๆ แล้วก็มีพายอร่อยๆ โปะด้วย!"
L37_1.m_Talk_THA = L38_1
L38_1 = "Tôi muốn một chiếc burger! Với một ít cà chua tươi và rau diếp giòn, và một miếng chả ngon ngọt ở trên!"
L37_1.m_Talk_VTN = L38_1
L38_1 = "我要吃汉堡！新鲜的西红柿，清脆的生菜，再加上厚厚的肉饼~"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Ich möchte einen Burger! Mit frischen Tomaten und knackigem Salat und einem saftigen Patty obendrauf!"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Je veux un hamburger ! Avec des tomates fraîches, des feuilles de laitue croquantes, et un pain bien croustillant !"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
