L39_1 = "m_Crash"
L38_1[L39_1] = 10
L39_1 = "크큭, 상상만 해도 입에 침이 고이는데~"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "くくっ、想像しただけでヨダレが出るよ～"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Ooh... My mouth is already watering!"
L38_1.m_Talk_ENG = L39_1
L39_1 = "咳咳，光是想想口水就要流下來了～"
L38_1.m_Talk_TWN = L39_1
L39_1 = "โอ้... น้ำลายสอแล้วเรา!"
L38_1.m_Talk_THA = L39_1
L39_1 = "Ôi... Tôi thèm chảy nước miếng rồi!"
L38_1.m_Talk_VTN = L39_1
L39_1 = "咳咳，光是想想口水就要流下来了~"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Oh! Mir läuft jetzt schon das Wasser im Mund zusammen!"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Ouah... j'en ai déjà l'eau à la bouche."
