L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 91
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 4800201
L41_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_Face = "UNIT_SURPRISE"
L42_1 = "SILKY_NPC_ESPR2_NULL"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "L"
L42_1 = "죄송해요, 루나님. 몸만 겨우 빠져나와서 외부인들이 쓰는 돈은 못 챙겨 왔어요."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "申し訳ありません、ルナ様。体だけどうにか脱出してきたので、領地外の人が使うお金は持っていないのです。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "I'm sorry, Ms. Luna, but I couldn't bring any outlander money with me because I barely made it out."
L41_1.m_Talk_ENG = L42_1
L42_1 = "對不起，露娜。因為好不容易才逃出來的，所以我沒帶外地人用的錢。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ขอโทษนะคะคุณลูน่า แต่ฉันไม่มีเงินของคนนอกติดตัวมาเลยค่ะ เพราะหาแทบไม่ได้เลย"
L41_1.m_Talk_THA = L42_1
L42_1 = "Tôi xin lỗi, cô Luna, nhưng tôi chẳng mang theo chút tiền nào, nên tôi không có tiền trả."
L41_1.m_Talk_VTN = L42_1
L42_1 = "对不起，露娜大人。因为好不容易才逃出来的，所以我没带外地人用的钱。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Es tut mir leid, Fräulein Luna, aber ich bin nur knapp entkommen, daher konnte ich das Geld, das Fremdlinge verwenden, nicht einstecken."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Désolée, madame Luna. Dans la panique, je n'ai pas eu le temps de prendre de l'argent avec moi..."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "ESPR2_ACT2_INTERLUDE1@92#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 92
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 4800201
L42_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "REGINA_ESPR_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "R"
L43_1 = "주머니가 넉넉했으면 히치하이킹도 안 했죠. 햄버거는 포기하세요, 루나."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "懐が暖かかったらヒッチハイクもしていませんわ。ハンバーガーは諦めてください、ルナさん。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "If we had money, we would not have resorted to hitchhiking in the first place. Give up on eating a hamburger, Luna."
L42_1.m_Talk_ENG = L43_1
L43_1 = "如果口袋裡有錢，我們也不用搭別人的順風車。漢堡就不要想了，露娜。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ถ้ามีเงินเราก็คงไม่ต้องโบกรถกันแต่แรกแล้ว เลิกคิดเรื่องกินเบอร์เกอร์ไปเถอะลูน่า"
L42_1.m_Talk_THA = L43_1
L43_1 = "Nếu chúng tôi có tiền, chúng tôi đã không cần đi nhờ xe ngay từ đầu. Đừng ăn hamburger nữa, Luna."
L42_1.m_Talk_VTN = L43_1
L43_1 = "如果口袋里有钱，我们也不用搭别人的顺风车。汉堡就不要想了，露娜。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Wenn wir Geld hätten, wären wir gar nicht erst per Anhalter gefahren. Den Hamburger kannst du dir schön abschminken, Luna."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Avec de l'argent, on aurait pas eu besoin de faire du stop pour commencer. Vous feriez mieux d'arrêter vos rêves de fast-food Luna, vous allez vous faire du mal."
L42_1.m_Talk_FRA = L43_1
