L47_1 = 2
L48_1 = 0.15
L46_1[1] = L47_1
L46_1[2] = L48_1
L44_1[L45_1] = L46_1
L45_1 = "뭐? 그럼 나더러 계속 쫄쫄 굶고 다니라고?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "はあ？　じゃあアタシにずっと飢えてろって？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "What?! Are you telling me that I should starve to death?!"
L44_1.m_Talk_ENG = L45_1
L45_1 = "什麼？那你是要我一直餓肚子嗎？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "หา?! จะบอกว่าฉันต้องหิวจนตายเหรอ?!"
L44_1.m_Talk_THA = L45_1
L45_1 = "Cái gì?! Ý cô là tôi nên chết đói sao?!"
L44_1.m_Talk_VTN = L45_1
L45_1 = "什么？那你是叫我一直饿肚子吗？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Was?! Willst du mir etwa sagen, dass ich verhungern soll?!"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Hein ? Alors quoi, je dois mourir de faim ?"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "ESPR2_ACT2_INTERLUDE1@95#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 95
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 4800201
L45_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_Face = "UNIT_HATE"
L46_1 = "TRUMPET_HARMONY_ESPR2_NULL"
L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "C"
L46_1 = "싫어 싫어! 햄버거 하나 못 사 주는 부학회장은 바보 멍텅구리!"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "やだやだ！　ハンバーガーひとつも買ってくれないなんて、副学会長のバカ！"
L45_1.m_Talk_JPN = L46_1
L46_1 = "No way! You silly Vice President! Buy me a burger!"
L45_1.m_Talk_ENG = L46_1
L46_1 = "討厭！連個漢堡都買不起的副學會長是大笨蛋！"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ไม่เอานะ! ฉันจะไม่ยอมกินอย่างอื่นหรอก! คุณเป็นถึงรองประธานแต่ซื้อเบอร์เกอร์โง่ๆ สักชิ้นให้ฉันไม่ได้เหรอเนี่ย?!"
L45_1.m_Talk_THA = L46_1
L46_1 = "Không! Tôi từ chối ăn bất cứ thứ gì nhưng! Cô là Phó Chủ Tịch mà cô thậm chí không mua nổi cho tôi một chiếc burger ngu ngốc sao?!"
L45_1.m_Talk_VTN = L46_1
L46_1 = "不要、不要！连个汉堡都买不起的副会长是个傻瓜大笨蛋！"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Das darf doch nicht wahr sein! Du dumme stellvertretende Gesellschaftsvorsitzende kannst mir also nicht einmal einen Hamburger kaufen?!"
L45_1.m_Talk_DEU = L46_1
L46_1 = "C'est mort, la vice-présidente de mes deux ! Achète-moi un hamburger, et plus vite que ça !"
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
