L49_1 = "부학회장님은 바보 멍텅구리 아니에요! 얼마나 좋은 분이신데요!"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "副学会長様はバカではありません！　本当に優しい方ですよ！"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Don't say that she's silly! She's such a kind, gentle being!"
L48_1.m_Talk_ENG = L49_1
L49_1 = "副學會長不是大笨蛋！她是個好人！"
L48_1.m_Talk_TWN = L49_1
L49_1 = "อย่าพูดแบบนั้นกับรองประธานนะคะ! เธอน่ะทั้งเป็นคนอ่อนโยนแล้วก็ใจดีด้วย!"
L48_1.m_Talk_THA = L49_1
L49_1 = "Đừng có nói thế với Phó Chủ Tịch! Cô ấy là người rất tốt bụng, tử tế!"
L48_1.m_Talk_VTN = L49_1
L49_1 = "副会长不是傻瓜大笨蛋！她是个好人！"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Die stellvertretende Gesellschaftsvorsitzende ist nicht dumm! Sie ist so eine liebenswerte Person!"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Ne lui parlez pas comme ça ! La vice-présidente est quelqu'un de bien."
L48_1.m_Talk_FRA = L49_1
