L2_1 = "ESPR2_ACT2_INTERLUDE1@101#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 101
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 4800201
L1_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "UNIT_DESPAIR"
L1_1.m_Face = L2_1
L2_1 = "REGINA_ESPR_NULL_NULL"
L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "C"
L2_1 = "후우……. 말릴 힘도 없으니 두 분 다 그만해 주세요. 저도 배가 고프긴 마찬가지입니다."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "ふう……止める元気もありませんから、二人ともそれくらいにしてください。私も空腹なのは同じなのです。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "*Sigh...* Will you two please knock it off? We are all hungry."
L1_1.m_Talk_ENG = L2_1
L2_1 = "呼……我連勸架的力氣都沒有，你們兩個都別再說了。我也一樣很餓。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "*เฮ้อ...* พอทีได้มั้ยนะเธอสองคนนี่? เราก็หิวจะแย่กันทั้งนั้นแหละ"
L1_1.m_Talk_THA = L2_1
L2_1 = "*Thở dài...* Hai người thôi đi được không? Tất cả chúng ta đều đang đói."
L1_1.m_Talk_VTN = L2_1
L2_1 = "呼……我连劝架的力气都没有，你们两个都别再说了。我也一样饿着呢。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "*Seufz* Ich habe nicht die Kraft, euch beide aufzuhalten, also hört bitte beide auf. Ich habe auch Hunger."
L1_1.m_Talk_DEU = L2_1
L2_1 = "*Soupir* Vous allez arrêter, toutes les deux ? On meurt tous de faim ici."
L1_1.m_Talk_FRA = L2_1
