L4_1 = "ESPR2_ACT2_INTERLUDE1@103#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 103
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 4800201
L3_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "USER_ADMIN_NULL_NULL"
L3_1.m_CharStrID = L4_1
L4_1 = "그래도 배가 든든해야 만약의 상황에 대처할 수 있지 않겠나?"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "でも、しっかり食べておかないと万が一の事態に備えられないぞ？"
L3_1.m_Talk_JPN = L4_1
L4_1 = "But won't having a full stomach help you deal with unexpected situations?"
L3_1.m_Talk_ENG = L4_1
L4_1 = "可我們需要吃飽飯，才能應付突發情況不是嗎？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "แต่ถ้าอิ่มท้องก็จะรับมือกับเรื่องไม่คาดคิดได้ไม่ใช่เหรอ?"
L3_1.m_Talk_THA = L4_1
L4_1 = "Nhưng chẳng phải một chiếc dạ dày no đủ sẽ giúp chúng ta đối phó với những tình huống bất ngờ hay sao?"
L3_1.m_Talk_VTN = L4_1
L4_1 = "可我们需要吃饱饭，才能应付突发情况不是吗？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Aber würde dir ein voller Magen nicht helfen, mit unerwarteten Situationen besser umzugehen?"
L3_1.m_Talk_DEU = L4_1
L4_1 = "... et pourtant, ce n'est pas en se remplissant la panse qu'on pourra mieux faire face aux imprévus."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "ESPR2_ACT2_INTERLUDE1@104#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 104
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 4800201
L4_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "USER_ADMIN_NULL_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "혹여 소식을 들은 프리드웬 친구들이 추적에 나설 수도 있으니 말이야."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "知らせを聞いたプリドウェンの者が追跡を始めることもあるだろうしな。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "For instance, Prydwen guys might've got word of your whereabouts and are tracking you down as we speak."
L4_1.m_Talk_ENG = L5_1
L5_1 = "普利多溫的人聽到消息後，也有可能追過來。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ตัวอย่างเช่น เพื่อนๆ ที่พริดเว็นของพวกคุณอาจได้ข่าวว่าพวกคุณอยู่ที่ไหนแล้วกำลังตามรอยมาตอนที่เราคุยกันอยู่นี่"
L4_1.m_Talk_THA = L5_1
L5_1 = "Chẳng hạn, những người bạn Prydwen của cô có thể lần ra cô ở đâu và tìm đến cô trong khi chúng ta đang nói chuyện."
L4_1.m_Talk_VTN = L5_1
L5_1 = "普利多温的人听到消息后，也有可能追过来。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Zum Beispiel haben die Typen von Prydwen möglicherweise deinen Aufenthaltsort herausgefunden und sind gerade dabei, dich aufzuspüren."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Qui sait, les types du Prydwen ont peut-être eu vent de notre aventure et ils sont à notre recherche à l'heure où je vous parle."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "ESPR2_ACT2_INTERLUDE1@105#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 105
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 4800201
L5_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "REGINA_ESPR_NULL_NULL"
L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "C"
L6_1 = "그렇죠. 리벳도 에델도 없이 저 혼자 기관 사람들에게서 벗어나긴…. 확실히 힘들겠네요."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "そうですわね。リベットもエデルもない今、私一人で機関の人たちから逃れるのは……確かに難しそうです。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Right. Without Edel or Rivet... I cannot possibly get away from the Institution..."
L5_1.m_Talk_ENG = L6_1
L6_1 = "是啊。里維和艾瑟兒也不在，光靠我自己，確實很難甩掉機關的人……"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ใช่ ถ้าไม่มีเอเดลหรือริเว็ตละก็... ฉันคงไม่มีปัญญาหนีพ้นจากพวกสถาบันนั่นได้..."
L5_1.m_Talk_THA = L6_1
L6_1 = "Đúng. Không có Edel hay Rivet... tôi không thể thoát khỏi Học Viện..."
L5_1.m_Talk_VTN = L6_1
L6_1 = "是啊。丽贝卡和埃德尔也不在，光靠我自己，确实很难甩掉机关的人……"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Stimmt. Ohne Edel oder Rivet kann ich dem Institut unmöglich entkommen ..."
L5_1.m_Talk_DEU = L6_1
L6_1 = "C'est vrai. Et sans Edel ou Rivet... Je ne peux pas échapper aux griffes de l'Institut."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "ESPR2_ACT2_INTERLUDE1@106#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 106
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 4800201
L6_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "UNIT_SERIOUS"
L6_1.m_Face = L7_1
L7_1 = "SILKY_NPC_ESPR2_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "C"
L7_1 = "위, 위험할 때는 제가 지켜 드릴게요. 마지막까지 꼭 부학회장님을 모실 테니까요."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "あ、危ない時には私がお守りします。最後まで必ず副学会長様に仕えますから。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "I-I'll protect you, ma'am. I won't leave you until the very end."
L6_1.m_Talk_ENG = L7_1
L7_1 = "遇…遇到危險時我會保護你的。我一定會陪伴副學會長到最後。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ฉะ-ฉันจะปกป้องคุณเองค่ะ ฉันจะไม่ทิ้งคุณจนลมหายใจสุดท้ายนะคะรองประธาน"
L6_1.m_Talk_THA = L7_1
L7_1 = "Tôi sẽ bảo vệ cô. Tôi sẽ không rời khỏi cô cho đến giây phút cuối cùng, Phó Chủ Tịch à."
L6_1.m_Talk_VTN = L7_1
L7_1 = "遇、遇到危险时我会保护你的。我一定会侍奉副会长到最后。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "I-ich werde Sie beschützen, stellvertretende Gesellschaftsvorsitzende. Ich werde bis zum bitteren Ende nicht von Ihrer Seite weichen."
L6_1.m_Talk_DEU = L7_1
L7_1 = "J-Je vous protégerai, madame. Jusqu'à mon dernier souffle !"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
