L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "C"
L8_1 = "그렇게 말해 주는 것만으로도 고마워요, 실키. 기운이 나네요."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "そう言ってくれるだけでもありがたいですわ、シルキー。元気が出ました。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Thank you for saying that even if you do not mean it, Sylkie. I feel a little better."
L7_1.m_Talk_ENG = L8_1
L8_1 = "你能這麼說，我就已經很感激了，思琪。我打起精神了。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ขอบคุณที่พูดถึงไม่ได้จะหมายความว่าอย่างนั้นจริงๆ นะซิลกี้ ฉันเบาใจขึ้นหน่อยเลย"
L7_1.m_Talk_THA = L8_1
L8_1 = "Cảm ơn cô đã nói điều đó kể cả khi không thực sự vậy, Sylkie. Tôi cảm thấy tốt hơn một chút rồi."
L7_1.m_Talk_VTN = L8_1
L8_1 = "你能这么说，我就已经很感激了，希尔琪。我打起精神了。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Danke, dass du das sagst, auch wenn du es nicht so meinst, Sylkie. Das heitert mich wirklich auf."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Merci Sylkie, vous êtes gentille. Je me sens un peu mieux maintenant."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
