L11_1 = "ESPR2_ACT2_INTERLUDE1@110#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 110
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 4800201
L10_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_IDLE"
L11_1 = "REGINA_ESPR_NULL_NULL"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "L"
L11_1 = "우선 주유소 주인에게 식량이 있는지 물어 보죠."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "まずはガソリンスタンドのオーナーに食糧があるか聞いてみましょう。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "First of all, let us go ask the gas station owner if they have anything to eat."
L10_1.m_Talk_ENG = L11_1
L11_1 = "先問問加油站的老闆有沒有吃的東西吧。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ก่อนอื่น เราไปถามเจ้าของปั๊มน้ำมันกันก่อนเถอะ ว่ามีอะไรให้กินมั้ย"
L10_1.m_Talk_THA = L11_1
L11_1 = "Trước hết, chúng ta hãy đi hỏi chủ cây xăng xem họ có gì để ăn không."
L10_1.m_Talk_VTN = L11_1
L11_1 = "先问问加油站的老板有没有吃的东西吧。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Wir sollten zunächst den Tankstellenbesitzer fragen, ob er etwas zu essen hat."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Bon, allons demander au gérant de la station-service s'il ne peut pas nous donner quelque chose à manger."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "ESPR2_ACT2_INTERLUDE1@111#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 4800201
L11_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "REGINA_ESPR_NULL_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "L"
L12_1 = "돈 대신 제 장신구로 거래할 수 있을 거예요. 장식은 수수해도 어엿한 진품이니까요."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "お金の代わりに私のアクセサリーで取引できるでしょう。装飾は控えめですがちゃんとした本物ですから。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "I will exchange my accessories instead of money. They might not look expensive, but they are worth enough."
L11_1.m_Talk_ENG = L12_1
L12_1 = "沒有錢，可以用我的飾品交換。飾品雖然很樸素，不過是珍貴的物品喔。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "เดี๋ยวฉันเอาเครื่องประดับจ่ายแทนเงินเอง อาจดูเหมือนไม่ค่อยแพงแต่แพงนะ"
L11_1.m_Talk_THA = L12_1
L12_1 = "Tôi sẽ trao đổi các phụ kiện của tôi để lấy tiền. Chúng có thể trông không đắt đỏ lắm, nhưng thực ra thì có đấy."
L11_1.m_Talk_VTN = L12_1
L12_1 = "没有钱，可以用我的饰品交换。虽然看起来很朴素，但也是珍贵的物品。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Ich werde mit meinen Accessoires statt Geld bezahlen. Sie sehen vielleicht nicht teuer aus, aber sie sind genug wert."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Je n'ai pas d'argent, mais j'ai des bijoux. Et ils valent leur poids d'or, même s'ils ne paient pas de mine."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
