L15_1 = "UNIT_DESPAIR"
L14_1.m_Face = L15_1
L15_1 = "REGINA_ESPR_NULL_NULL"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "L"
L15_1 = "……방금까지 다 죽어가는 것처럼 굴더니 기운이 넘치네."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "……さっきまでは死にそうな様子でしたのに、元気いっぱいね。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "...She acted as if she were dying, but now she is alive and well."
L14_1.m_Talk_ENG = L15_1
L15_1 = "……剛才還好像一副要死掉的樣子，現在來精神了呢。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "เมื่อกี้ยังทำท่าอย่างกับจะตาย พอตอนนี้ล่ะร่าเริงขึ้นมาเชียว"
L14_1.m_Talk_THA = L15_1
L15_1 = "Cô ấy làm như sắp chết, thế mà bây giờ lại nhảy nhót tưng bừng."
L14_1.m_Talk_VTN = L15_1
L15_1 = "……刚才还一副好像快要死掉的样子，现在来精神了。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "... Sie tat bis gerade eben noch so, als wäre sie kurz davor, den Löffel abzugeben, aber jetzt ist sie wieder putzmunter."
L14_1.m_Talk_DEU = L15_1
L15_1 = "... Elle était au bord de l'agonie tout à l'heure, je vois que ça va mieux."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "ESPR2_ACT2_INTERLUDE1@115#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 115
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 4800201
L15_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_LAUGH"
L16_1 = "SILKY_NPC_ESPR2_NULL"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "R"
L16_1 = "정말요. 꼭 말 안 듣는 개구쟁이 동생이 생긴 것 같아요."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "本当ですね。まるで言うことを聞かないやんちゃな妹ができたような気分です。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "I know. It's like I now have a mischievous little sister."
L15_1.m_Talk_ENG = L16_1
L16_1 = "真的呢。就好像有了一個不聽話的調皮妹妹。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "จริงค่ะ อย่างกับเรามีน้องสาวเกเรเลยตอนนี้"
L15_1.m_Talk_THA = L16_1
L16_1 = "Tôi biết. Giống như một cô em gái tinh nghịch ấy."
L15_1.m_Talk_VTN = L16_1
L16_1 = "真的呢。这就好像是有了一个不听话的淘气妹妹一样。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Stimmt. Ich habe das Gefühl, eine freche kleine Schwester zu haben, die mir nicht zuhört."
L15_1.m_Talk_DEU = L16_1
L16_1 = "M'en parlez pas. J'ai l'impression d'avoir une petite sœur avec un déficit d'attention."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "ESPR2_ACT2_INTERLUDE1@116#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 116
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 4800201
L16_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "REGINA_ESPR_NULL_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "L"
L17_1 = "왜 내 주위에는 저런 괴짜들만 꼬이는지……"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "どうして私の周りにはああいった変わり者ばかり集まるのかしら……"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Why do all the weird ones gather around me...?"
L16_1.m_Talk_ENG = L17_1
L17_1 = "為什麼我的身邊總是只有這種怪人呢……"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ทำไมรอบตัวฉันถึงต้องมีแต่คนประหลาดๆ ด้วยนะ...?"
L16_1.m_Talk_THA = L17_1
L17_1 = "Tại sao quanh tôi toàn những người kỳ lạ thế ...?"
L16_1.m_Talk_VTN = L17_1
L17_1 = "为什么我的身边总是只有这种怪人呢……"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Warum scheine ich bloß solche komischen Leute magisch anzuziehen ...?"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Pourquoi je ne croise que des tarés, moi ?"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "ESPR2_ACT2_INTERLUDE1@117#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 117
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 4800201
L17_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "UNIT_DESPAIR"
L17_1.m_Face = L18_1
L18_1 = "SILKY_NPC_ESPR2_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "R"
L18_1 = "언니들도 저를 키울 때 이런 기분이었겠죠…."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "お姉さんたちも私を育てる時にはこんな気持ちだったんでしょうね……"
L17_1.m_Talk_JPN = L18_1
L18_1 = "I bet my older sisters felt like this when they looked after me."
L17_1.m_Talk_ENG = L18_1
L18_1 = "姊姊們養育我的時候，應該就是這種心情吧……"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ตอนดูแลฉันพี่สาวฉันก็คงรู้สึกแบบนี้เหมือนกันแหละค่ะ"
L17_1.m_Talk_THA = L18_1
L18_1 = "Tôi cá là các chị tôi cũng cảm thấy thế này khi họ chăm sóc tôi."
L17_1.m_Talk_VTN = L18_1
L18_1 = "姐姐们养育我的时候，应该就是这种心情吧……"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Ich wette, meine älteren Schwestern haben sich so gefühlt, als sie sich um mich gekümmert haben."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Est-ce que mes grandes sœurs me voyaient comme ça, elles aussi ?"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
