L22_1 = "USER_ADMIN_NULL_NULL"
L21_1.m_CharStrID = L22_1
L22_1 = "매번 괴짜만 꼬이는 것 같으면 본인 문제가 아닐지 돌아봐야 하지 않겠나?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "毎回変わり者ばかりが集まるのなら、本人の問題ではないか振り返ってみる必要があるんではないかな？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Maybe it's not them, but you who is the problem?"
L21_1.m_Talk_ENG = L22_1
L22_1 = "如果身邊總是有怪人的話，那你應該反省下是不是自己的問題吧？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "บางทีอาจไม่ใช่คนอื่น แต่คุณเองรึเปล่าที่เป็นปัญหาน่ะ?"
L21_1.m_Talk_THA = L22_1
L22_1 = "Có lẽ không phải họ, mà chính cô mới là vấn đề thì sao?"
L21_1.m_Talk_VTN = L22_1
L22_1 = "如果身边总是有怪人的话，那你应该反思下是不是自己的问题吧？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Wenn du das Gefühl hast, ständig in Schwierigkeiten zu geraten, solltest du dann nicht mal prüfen, ob du das Problem bist?"
L21_1.m_Talk_DEU = L22_1
L22_1 = "S'il n'y a que des fous sur ton chemin, tu pourrais peut-être te demander si le problème ne vient pas de toi ?"
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
