L27_1 = "ESPR2_ACT2_INTERLUDE1@126#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 126
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 4800201
L26_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "SILKY_NPC_ESPR2_NULL"
L26_1.m_CharStrID = L27_1
L27_1 = "L_M_I"
L26_1.m_Pos = L27_1
L27_1 = "와아, 외부인들은 정말 이런 동굴 같은 곳에서 사네요. 실제로는 처음 봤어요."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "わあ、領地外の人は本当にこんな洞窟みたいなところに住んでいるのですね。実際に見るのは初めてです。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Wow...! Outlanders really do live in caves like this. It's my first time seeing one in person."
L26_1.m_Talk_ENG = L27_1
L27_1 = "哇啊，外地人真的住在這種洞窟一樣的地方啊。我還是第一次看到實物。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "โห...! พวกคนนอกอาศัยในถ้ำแบบนี้จริงด้วยนะคะนี่ เพิ่งเคยเห็นกับตาก็คราวนี้แหละ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Wow...! Người kẻ ngoại lai thực sự sống trong những hang động như thế này. Đây là lần đầu tiên tôi nhìn thấy họ."
L26_1.m_Talk_VTN = L27_1
L27_1 = "哇啊，外地人真的住在这种洞窟一样的地方啊。我还是第一次看到实物。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Wow! Fremdlinge leben tatsächlich in solchen Höhlen. Es ist das erste Mal, dass ich eine in echt sehe."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Ouah... ! Les étrangers vivent vraiment dans des grottes, alors ? Incroyable !"
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "ESPR2_ACT2_INTERLUDE1@127#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 127
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 4800201
L27_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "TRUMPET_HARMONY_ESPR2_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "R"
L28_1 = "에이, 이게 뭐야. 가게가 아니라 폐가잖아."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "ええ、何これ。店じゃなくて廃屋じゃん。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Eww, seriously? This isn't a shop, it's a ruin."
L27_1.m_Talk_ENG = L28_1
L28_1 = "哎唷，什麼嘛，這裡不是店家，而是個廢屋啊。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "อี๋ ถามจริ๊ง? นี่มันไม่ใช่ร้านแล้วเนี่ย ซากชัดๆ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Eww, nghiêm túc chứ? Đây không phải là một cửa hàng, nó là một phế tích."
L27_1.m_Talk_VTN = L28_1
L28_1 = "诶，什么嘛，这儿完全不像是商店，而是个废宅嘛！"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Hä?! Was ist das denn? Das ist doch kein Laden, das ist eine Ruine."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Euh, quoi ? C'est pas un magasin ça, c'est un champ de ruines."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
