L30_1 = "ESPR2_ACT2_INTERLUDE1@129#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 129
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 4800201
L29_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_IDLE"
L30_1 = "REGINA_ESPR_NULL_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "C"
L30_1 = "그러게요. 햄버거는 기대를 접어야겠네요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "そうですね。ハンバーガーは諦めた方が良さそうですわ。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "I suppose so. I assume there are no hamburgers here."
L29_1.m_Talk_ENG = L30_1
L30_1 = "是啊，那你對漢堡的期待就泡湯了呢。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ฉันก็ว่างั้น สงสัยจะไม่มีเบอร์เกอร์แล้วล่ะที่นี่"
L29_1.m_Talk_THA = L30_1
L30_1 = "Tôi cho là vậy. Tôi cá là chẳng có chiếc burger nào ở đây."
L29_1.m_Talk_VTN = L30_1
L30_1 = "是啊，那你对汉堡的期待，就泡汤了咯。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Sieht so aus. Ich gehe mal ganz stark davon aus, dass es hier keine Hamburger gibt."
L29_1.m_Talk_DEU = L30_1
L30_1 = "En effet. Ça m'étonnerait qu'ils vendent des hamburgers ici."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
