L32_1 = "ESPR2_ACT2_INTERLUDE1@131#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 4800201
L31_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "TRUMPET_HARMONY_ESPR2_NULL"
L31_1.m_CharStrID = L32_1
L32_1 = "어째 잘됐다는 투로 말한다?"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "なんだか、しめたって口調だね？"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Why do you sound relieved?"
L31_1.m_Talk_ENG = L32_1
L32_1 = "你怎麼一副暗爽的口氣？"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ทำไมฟังดูโล่งใจจังละนั่น?"
L31_1.m_Talk_THA = L32_1
L32_1 = "Tại sao cô có vẻ nhẹ nhõm như vậy?"
L31_1.m_Talk_VTN = L32_1
L32_1 = "哼！你怎么一副幸灾乐祸的口气啦？"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Warum klingst du so erleichtert?"
L31_1.m_Talk_DEU = L32_1
L32_1 = "C'est moi où tu as l'air contente, là ?"
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "ESPR2_ACT2_INTERLUDE1@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 4800201
L32_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "UNIT_SERIOUS"
L32_1.m_Face = L33_1
L33_1 = "REGINA_ESPR_NULL_NULL"
L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "C"
L33_1 = "말도 안 되는 편지 한 장 가지고 절 가둬 둔 대가라고 생각하세요."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "お話にもならないような手紙一枚で私を閉じ込めた罰だと思いなさい。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Think of it as payback for locking me up in a room because a letter told you to."
L32_1.m_Talk_ENG = L33_1
L33_1 = "就當是你拿著一封完全說不通的信，把我關起來的代價吧。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "คิดซะว่าเอาคืนที่ขังฉันไว้ในห้องเพราะจดหมายที่ฉันบอกให้ทำแล้วกัน"
L32_1.m_Talk_THA = L33_1
L33_1 = "Cứ coi như đó là sự đền đáp vì đã nhốt tôi trong phòng chỉ vì có một lá thư yêu cầu cô làm vậy."
L32_1.m_Talk_VTN = L33_1
L33_1 = "就当是你拿着一封莫名其妙的信，把我关起来的代价吧？"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Betrachte es als Rache dafür, dass du mich in diesem Zimmer eingesperrt hast, nur weil dich so ein lächerlicher Brief dazu aufgefordert hatte."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Considérez que c'est ma petite vengeance, après que vous m'avez enfermée dans cette prison sur ordre d'une simple lettre."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
