L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 4800201
L34_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "SILKY_NPC_ESPR2_NULL"
L34_1.m_CharStrID = L35_1
L35_1 = "부학회장님, 여기 좀 보세요."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "副学会長様、これを見てください。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Vice President, look over here."
L34_1.m_Talk_ENG = L35_1
L35_1 = "副學會長，你看這裡。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "รองประธานคะ มาดูนี่สิคะ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Phó Chủ Tịch, nhìn chỗ này nè."
L34_1.m_Talk_VTN = L35_1
L35_1 = "副会长，你看这里。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Stellvertretende Gesellschaftsvorsitzende, schauen Sie mal hier."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Regardez ici, madame !"
L34_1.m_Talk_FRA = L35_1
