L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 4800201
L36_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_Face = "UNIT_LAUGH"
L37_1 = "SILKY_NPC_ESPR2_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "L"
L37_1 = "유리병 안에 신기한 게 들어 있어요. 알록달록해서 무척 예뻐요."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "ガラス瓶の中に不思議なものが入っていますよ。色とりどりでとても綺麗です。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "There's something strange inside this glass jar. They're all colorful and pretty."
L36_1.m_Talk_ENG = L37_1
L37_1 = "玻璃瓶裡有神奇的東西。五顏六色的，很漂亮。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "มีอะไรแปลกๆ ในโหลแก้วด้วยค่ะ หลายสี สวยด้วย"
L36_1.m_Talk_THA = L37_1
L37_1 = "Có gì đó bên trong lọ thủy tinh này lạ quá. Chúng đều sặc sỡ và xinh đẹp."
L36_1.m_Talk_VTN = L37_1
L37_1 = "玻璃瓶里有神奇的东西。五颜六色的，很漂亮。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "In diesem Glasgefäß ist etwas Seltsames. Es ist so bunt und hübsch."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Il y a quelque chose de bizarre à l'intérieur de ces bocaux. C'est tout coloré et pétillant..."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "ESPR2_ACT2_INTERLUDE1@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 4800201
L37_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "REGINA_ESPR_NULL_NULL"
L37_1.m_CharStrID = L38_1
L38_1 = "R_M_I"
L37_1.m_Pos = L38_1
L38_1 = "이건 사탕이에요. 제가 어릴 때 먹은 제품인데 아직도 파네요."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "これはキャンディーです。私が小さい頃に食べていた製品ですが、まだ売っているのですね。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Those are called candies. It is the exact one I used to eat as a kid. I am surprised they still sell them."
L37_1.m_Talk_ENG = L38_1
L38_1 = "這是糖果。我小時候吃過的東西，沒想到現在還在賣。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "อันนั้นเรียกลูกอมน่ะ เหมือนที่ฉันเคยกินตอนเด็กเลย แปลกใจนะที่ยังมีขายอยู่"
L37_1.m_Talk_THA = L38_1
L38_1 = "Chúng được gọi là kẹo. Đó chính xác là món tôi từng ăn khi còn bé. Tôi ngạc nhiên là họ vẫn còn bán chúng."
L37_1.m_Talk_VTN = L38_1
L38_1 = "这是糖果。我小时候吃过的东西，没想到现在还在卖。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Das nennt man „Süßigkeiten“. Es ist genau das, was ich als Kind gegessen habe. Ich bin überrascht, dass sie immer noch verkauft werden."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Ce sont des bonbons, les mêmes que je mangeais quand j'étais enfant. Je suis surprise de voir qu'on en vend toujours."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
