L41_1 = "ESPR2_ACT2_INTERLUDE1@140#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 4800201
L40_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_Face = "UNIT_IDLE"
L41_1 = "REGINA_ESPR_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "R"
L41_1 = "네. 입에 물고 있으면 계속 달콤한 맛이 나는 과자입니다."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "はい。口に含んでいるとずっと甘い味がするお菓子ですわ。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Yes. You put one in your mouth and let its sweetness melt."
L40_1.m_Talk_ENG = L41_1
L41_1 = "是的，含在嘴裡，就一直有甜味。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ใช่ เอาเข้าปากแล้วก็อมให้หวานๆ ละลายๆ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Đúng. Cô cho một chiếc vào miệng và nó sẽ chảy ra vị ngọt."
L40_1.m_Talk_VTN = L41_1
L41_1 = "是的，含在嘴里，就一直有甜味。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Genau. Es ist ein Snack, der einen süßen Geschmack im Mund hinterlässt."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Oui. Il suffit d'en déposer un sur sa langue, et de se laisser enivrer par sa douceur."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "ESPR2_ACT2_INTERLUDE1@141#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 4800201
L41_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_Face = "UNIT_SURPRISE"
L42_1 = "SILKY_NPC_ESPR2_NULL"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "L"
L42_1 = "정말요? 제가 영지 바깥을 잘 모른다고 놀리시는 거 아니죠?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "本当ですか？　私が領地の外をよく知らないからといって、からかってるのではありませんよね？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Really? You're not making fun of me because it's my first time being out here, are you?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "真的嗎？你不會因為我不知道領地外面的事，故意捉弄我吧？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "จริงเหรอคะ? คุณไม่ได้หลอกเล่นเพราะฉันเพิ่งเคยออกมาข้างนอกใช่มั้ยคะ?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Thật sao? Cô không trêu tôi vì đây là lần đầu tiên tôi ra thế giới bên ngoài đấy chứ?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "真的吗？我、我不怎么了解领地外面的事，请不要故意戏弄我……"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Wirklich? Sie machen sich aber gerade nicht über mich lustig, weil ich nicht viel über die Welt außerhalb der Domain weiß, oder?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "C'est possible, ça ? Vous vous moquez de moi parce que je ne connais rien, n'est-ce pas ?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
