L44_1 = "ESPR2_ACT2_INTERLUDE1@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 4800201
L43_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "USER_ADMIN_NULL_NULL"
L43_1.m_CharStrID = L44_1
L44_1 = "맥크레디 양 말이 맞다네. 그 대신 먹고 나면 이빨을 꼭 닦아야 하지."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "マクレディー君の話は本当さ。その代わりに食べた後には必ず歯を磨かないといけない。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Regina is telling the truth. But make sure to brush your teeth after having one."
L43_1.m_Talk_ENG = L44_1
L44_1 = "麥克蕾蒂說的沒錯。是可以吃的東西，不過吃完之後，必須好好刷牙。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "เรจิน่าพูดจริงนะ แต่กินแล้วอย่าลืมแปรงฟันล่ะ"
L43_1.m_Talk_THA = L44_1
L44_1 = "Regina đang nói thật đấy. Nhưng hãy nhớ đánh răng sau khi ăn kẹo."
L43_1.m_Talk_VTN = L44_1
L44_1 = "麦克雷迪说的没错。是可以吃的东西，不过吃完之后，必须好好刷牙。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Regina sagt die Wahrheit. Aber achte darauf, deine Zähne zu putzen, nachdem du sie gegessen hast."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Mademoiselle MacCready dit la vérité. Mais tu dois absolument te brosser les dents après en avoir mangé."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "ESPR2_ACT2_INTERLUDE1@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 4800201
L44_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "USER_ADMIN_NULL_NULL"
L44_1.m_CharStrID = L45_1
L45_1 = "깜빡하고 자면 아주 무서운 일이 벌어질 거야…."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "うっかり眠ってしまうと、とても恐ろしいことになるぞ……"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Something very scary will happen if you forget and just go to bed..."
L44_1.m_Talk_ENG = L45_1
L45_1 = "忘記刷牙就睡覺的話，會發生很可怕的事……"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ถ้าลืมแล้วไปนอนจะเกิดเรื่องน่ากลัวมากๆ ขึ้นนะ..."
L44_1.m_Talk_THA = L45_1
L45_1 = "Sẽ có điều rất kinh khủng xảy ra nếu cô quên mất và cứ thế đi ngủ..."
L44_1.m_Talk_VTN = L45_1
L45_1 = "忘记刷牙就睡觉的话，会发生很可怕的事……"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Etwas sehr Beängstigendes wird passieren, wenn du es vergisst und einfach ins Bett gehst ..."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Si tu oublies, quelque chose de terrible se produira quand tu iras te coucher..."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "ESPR2_ACT2_INTERLUDE1@145#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 145
L45_1.m_CutScenProcessKey = L46_1
