L46_1 = "m_Crash"
L45_1[L46_1] = 20
L46_1 = "저주가 걸려 있어서 그렇군요! 그럴 줄 알았어요!"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "呪いがかけられているからですね！　そうだと思いました！"
L45_1.m_Talk_JPN = L46_1
L46_1 = "So it's cursed! I knew it!"
L45_1.m_Talk_ENG = L46_1
L46_1 = "原來它上面有詛咒啊！我就知道會是這樣！"
L45_1.m_Talk_TWN = L46_1
L46_1 = "มันต้องสาปสินะคะ! ว่าแล้วเชียว!"
L45_1.m_Talk_THA = L46_1
L46_1 = "Vậy ra nó là đồ vật bị nguyền rủa! Tôi biết mà!"
L45_1.m_Talk_VTN = L46_1
L46_1 = "原来它上面有诅咒？我就知道会是这样……"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Also sind sie verflucht! Ich hab es doch gewusst!"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Alors ces choses sont maudites ! Je le savais !"
L45_1.m_Talk_FRA = L46_1
