L47_1 = "UNIT_DESPAIR"
L46_1.m_Face = L47_1
L47_1 = "REGINA_ESPR_NULL_NULL"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "R"
L47_1 = "사장님. 성실한 아이에게 오해할 만한 소리 하지 마세요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "社長。真面目な子が誤解するようなことを言わないでください。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Boss. Please do not say things that she might misunderstand."
L46_1.m_Talk_ENG = L47_1
L47_1 = "老闆，請不要說一些會讓誠實的孩子產生誤會的話。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "บอสคะ ขอล่ะ อย่าพูดอะไรให้เธอเข้าใจผิดเลย"
L46_1.m_Talk_THA = L47_1
L47_1 = "Ông Chủ à. Làm ơn đừng nói những điều khiến cô ấy hoang tưởng nữa đi."
L46_1.m_Talk_VTN = L47_1
L47_1 = "老板，请不要说一些会让诚实的孩子产生误会的话。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Boss. Bitte sagen Sie nichts, was sie missverstehen könnte."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Allons, boss. Ne lui dites pas des choses pareilles, elle pourrait vous croire."
L46_1.m_Talk_FRA = L47_1
