L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 148
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 4800201
L48_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_Face = "UNIT_IDLE"
L49_1 = "REGINA_ESPR_NULL_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "하나쯤은 사 줘도 좋겠는데 포장지에 적힌 년도가……"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "一つくらいは買ってあげてもいいのですが、包み紙に刻印されている年度が……"
L48_1.m_Talk_JPN = L49_1
L49_1 = "I guess I could buy her one. I wonder what the expiration date is..."
L48_1.m_Talk_ENG = L49_1
L49_1 = "我可以給你買一個，包裝紙上寫的年份是……"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ฉันว่าฉันน่าจะซื้อให้เธอได้อยู่ สงสัยจังว่าหมดอายุเมื่อไหร่..."
L48_1.m_Talk_THA = L49_1
L49_1 = "Chắc là tôi có thể mua cho cô ấy một chiếc. Không biết nó hết hạn chưa..."
L48_1.m_Talk_VTN = L49_1
L49_1 = "我可以给你买一个，包装纸上写的年份是……"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Ich schätze, ich könnte ihr eine kaufen. Ich frage mich, was das Verfallsdatum ist ..."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Je peux bien lui en acheter quelques uns, non ? Je me demande s'ils ont une date d'expiration..."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
