L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 149
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 4800201
L49_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
