L50_1 = "UNIT_DESPAIR"
L49_1.m_Face = L50_1
L50_1 = "REGINA_ESPR_NULL_NULL"
L49_1.m_CharStrID = L50_1
L49_1.m_Pos = "C"
L50_1 = "으음. 안 되겠네요. 50년은 더 지났어요."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "うーん、駄目ですわね。50年は過ぎています。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Hmm... No good. It expired 50 years ago."
L49_1.m_Talk_ENG = L50_1
L50_1 = "呃嗯，不行呢，已經過期50年了。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "อืมม... ไม่ดีละ หมดอายุไปตั้ง 50 ปีแล้วเนี่ย"
L49_1.m_Talk_THA = L50_1
L50_1 = "Hmm... Không ổn. Nó đã hết hạn cách đây 50 năm rồi."
L49_1.m_Talk_VTN = L50_1
L50_1 = "呃嗯，不行呢，已经过期50年了。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Hmm. Oh, wie schade. Sie sind bereits vor 50 Jahren abgelaufen."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Euh... périmé depuis 50 ans. C'est une blague ?"
