L50_1.m_Face = "UNIT_SURPRISE"
L51_1 = "SILKY_NPC_ESPR2_NULL"
L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "C"
L51_1 = "앗, 전 괜찮아요, 부학회장님. 정말 아무렇지도 않아요."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "あっ、お気になさらないでください、副学会長様。本当になんてことありません。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Oh, it's okay, ma'am. I don't mind."
L50_1.m_Talk_ENG = L51_1
L51_1 = "啊，我沒關係，副學會長。我不會在意的。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "อ๋อ ไม่เป็นไรหรอกค่ะ ฉันไม่ถือ"
L50_1.m_Talk_THA = L51_1
L51_1 = "Ồ, không sao đâu, thưa cô. Tôi không phiền đâu mà."
L50_1.m_Talk_VTN = L51_1
L51_1 = "啊，我没关系，副会长。我不会在意的。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Ach, schon okay, stellvertretende Gesellschaftsvorsitzende. Es macht mir nichts aus."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Ça va madame, ne vous en faites pas pour moi."
L50_1.m_Talk_FRA = L51_1
