L2_1 = "ESPR2_ACT2_INTERLUDE1@151#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 151
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 4800201
L1_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "UNIT_SERIOUS"
L1_1.m_Face = L2_1
L2_1 = "REGINA_ESPR_NULL_NULL"
L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "C"
L2_1 = "제가 안 괜찮아요. 영지의 주민들은 살면서 사탕 한 알 제대로 맛보지 못한다는 거니까."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "私が気にしますわ。領地の住民が生涯にキャンディーのひとつも味わえないことになるのですから。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "I do. It is my fault the residents at the estate do not know what candy tastes like."
L1_1.m_Talk_ENG = L2_1
L2_1 = "可我在意。作為領地的居民，有生以來居然連一顆糖果都沒吃過。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "แต่ฉันถือ ที่ผู้อยู่อาศัยในพื้นที่ไม่รู้ว่าลูกอมรสชาติเป็นยังไงนี่ความผิดฉันนะ"
L1_1.m_Talk_THA = L2_1
L2_1 = "Có đấy. Đó là lỗi của tôi khi cư dân tại lãnh địa còn chẳng biết kẹo có vị gì."
L1_1.m_Talk_VTN = L2_1
L2_1 = "可我在意。作为领地的居民，有生以来居然连一颗糖果都没吃过。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Nein, es ist gar nicht okay. Es ist allein meine Schuld, dass die Bewohner der Domain nicht wissen, wie Süßigkeiten schmecken."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Non, c'est de ma faute. Ma faute si les habitants du domaine n'ont jamais pu goûter à un bonbon de leur vie."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "ESPR2_ACT2_INTERLUDE1@152#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 152
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 4800201
L2_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_Face = "UNIT_IDLE"
L3_1 = "REGINA_ESPR_NULL_NULL"
L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "C"
L3_1 = "영지 바깥에는 사탕 말고도 맛있는 과자가 많아요."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "領地の外にはキャンディー以外にもおいしいお菓子がたくさんあります。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Out of the estate, there are more delicious snacks other than just candy."
L2_1.m_Talk_ENG = L3_1
L3_1 = "領地外面除了糖果，還有很多好吃的餅乾。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ข้างนอกนี่มีของกินเล่นอร่อยๆ กว่าลูกอมอีกเยอะเลยล่ะ"
L2_1.m_Talk_THA = L3_1
L3_1 = "Ở chỗ này có nhiều món ăn vặt ngon hơn cả kẹo."
L2_1.m_Talk_VTN = L3_1
L3_1 = "领地外面除了糖果，还有很多好吃的饼干。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Außerhalb der Domain gibt es außer Süßigkeiten noch andere leckere Snacks."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Le monde extérieur est rempli de choses délicieuses, vous savez ? Plus délicieuses encore que ces bonbons."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "ESPR2_ACT2_INTERLUDE1@153#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 4800201
L3_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_LAUGH"
L4_1 = "REGINA_ESPR_NULL_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "C"
L4_1 = "간병의 대가로 꼭 잔뜩 대접해 줄게요."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "看病の対価として山ほどご馳走すると約束しますわ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "As my caregiver, I will make sure you try them."
L3_1.m_Talk_ENG = L4_1
L4_1 = "我一定給你買一大堆，就當是你照顧我的謝禮。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "เธอเป็นผู้ดูแลฉันนี่ เดี๋ยวฉันจะให้ได้กินแน่ๆ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Là người chăm sóc của tôi, tôi sẽ đảm bảo cô được nếm thử chúng."
L3_1.m_Talk_VTN = L4_1
L4_1 = "我一定给你买一大堆，就当是你照顾我的谢礼。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Da du meine Betreuerin bist, werde ich dafür sorgen, dass du sie einmal probieren kannst."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Je vous promets de vous en offrir, pour vous remercier d'avoir veillé sur moi."
L3_1.m_Talk_FRA = L4_1
