L6_1 = "USER_ADMIN_NULL_NULL"
L5_1.m_CharStrID = L6_1
L6_1 = "저런. 하루 종일 이빨만 닦아야겠군, 실키 양."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "おっと。一日中歯磨きをしないといけないな、シルキー君。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Oh dear. You'll be brushing your teeth all day long, Sylkie."
L5_1.m_Talk_ENG = L6_1
L6_1 = "哎呀，那你一整天都得刷牙呢，思琪。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "โอ้ตายล่ะ เธอได้แปรงฟันทั้งวันแน่ซิลกี้"
L5_1.m_Talk_THA = L6_1
L6_1 = "Ôi trời. Cô sẽ phải đánh răng cả ngày đấy, Sylkie."
L5_1.m_Talk_VTN = L6_1
L6_1 = "哎呀，那你一整天都得刷牙呢，希尔琪。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Oh je. Du wirst den ganzen Tag deine Zähne putzen müssen, Sylkie."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Oups. Tu es partie pour te brosser les dents toute la journée, Sylkie."
L5_1.m_Talk_FRA = L6_1
