L8_1 = "한 번만 더 놀리면 새장에 가둬 놓고 다니겠습니다."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "もう一度からかうようなら鳥かごに入れますわよ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "You tease her one more time and I will put you in a cage."
L7_1.m_Talk_ENG = L8_1
L8_1 = "你要是再捉弄她，我就把你關進鳥籠裡。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "แกล้งเธออีกทีฉันจะจับคุณใส่กรงแล้วนะ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Ông cứ trêu cô ấy nữa là tôi sẽ nhốt vào lồng đấy."
L7_1.m_Talk_VTN = L8_1
L8_1 = "你要是再戏弄她，我就把你关进鸟笼里，老板。"
L7_1.m_Talk_SCN = L8_1
