L14_1 = "ハンバーガーもろくに食べられないなんて……こんなのないよ……"
L13_1.m_Talk_JPN = L14_1
L14_1 = "I can't even have a lousy burger...? What kind of cruel joke is that...?"
L13_1.m_Talk_ENG = L14_1
L14_1 = "連個漢堡都不能隨便吃……怎麼會這樣……"
L13_1.m_Talk_TWN = L14_1
L14_1 = "เบอร์เกอร์ง่อยๆ ยังจะไม่ได้กินเลยเหรอเนี่ย...? ตลกร้ายใจยักษ์อะไรขนาดนี้?"
L13_1.m_Talk_THA = L14_1
L14_1 = "Tôi thậm chí còn chẳng có được một chiếc burger tử tế sao...? Đùa gì ác thế...?"
L13_1.m_Talk_VTN = L14_1
L14_1 = "连个汉堡都不能随便吃……怎么会这样……"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Ich kann nicht mal einen Burger essen ... Das kann doch wohl nicht wahr sein ..."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Je peux même pas avoir un seul hamburger... ? C'est quoi cette blague ?"
L13_1.m_Talk_FRA = L14_1
