L16_1 = "CUTSCENE_TALK_02"
L15_1.m_StartBGMFileName = L16_1
L16_1 = "FX_CUTSCEN_DOOR_SLIDE"
L15_1.m_StartFXSoundName = L16_1
L16_1 = "OLD_NPC_ESPR2_NULL"
L15_1.m_CharStrID = L16_1
L16_1 = "뭐야, 왜 이리 시끄러워……."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "お前たち何だ、騒がしくして……"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Huh? What's going on out there...?"
L15_1.m_Talk_ENG = L16_1
L16_1 = "怎麼回事，為什麼這麼吵……"
L15_1.m_Talk_TWN = L16_1
L16_1 = "หือ? ข้างนอกนั่นเกิดอะไรขึ้นน่ะ...?"
L15_1.m_Talk_THA = L16_1
L16_1 = "Huh? Ngoài kia ầm ĩ cái gì vậy...?"
L15_1.m_Talk_VTN = L16_1
L16_1 = "怎么回事，为什么这么吵……"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Hä? Wer macht denn hier so einen Lärm ...?"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Hmm ? C'est quoi ce vacarme ?"
L15_1.m_Talk_FRA = L16_1
