L17_1 = "ESPR2_ACT2_INTERLUDE1@166#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 166
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 4800201
L16_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Face = "UNIT_SURPRISE"
L17_1 = "REGINA_ESPR_NULL_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "C"
L17_1 = "아. 죄송합니다. 너무 어질러져 있어서 영업을 안 하시는 줄 알았어요."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "あ。申し訳ございません。あまりにも散らかっていたので、営業をされていないのかと思いました。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Oh, my apologies. It was so dirty that we assumed this shop was abandoned."
L16_1.m_Talk_ENG = L17_1
L17_1 = "啊，對不起，這裡太亂了，我們還以為不營業了呢。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "โอ๊ะ ขออภัยด้วยค่ะ มักรกเกินไปจนฉันนึกว่าร้านนี้ร้างอ่ะ"
L16_1.m_Talk_THA = L17_1
L17_1 = "Ồ, xin lỗi nhé. Cửa hàng này bẩn thỉu đến mức tôi tưởng nó bị bỏ hoang rồi chứ."
L16_1.m_Talk_VTN = L17_1
L17_1 = "啊，对不起，这里太乱了，我们还以为不营业了呢。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Oh, Entschuldigung. Es war hier so dreckig, dass wir annahmen, dass dieser Laden nicht mehr in Betrieb ist."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Oh, mes excuses. Vu son état, nous pensions que cette boutique était abandonnée..."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
