L19_1 = "ESPR2_ACT2_INTERLUDE1@168#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 168
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 4800201
L18_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "OLD_NPC_ESPR2_NULL"
L18_1.m_CharStrID = L19_1
L19_1 = "다 너희 같이 버르장머리 없는 어린 것들이 들쑤시고 다닌 탓이지. 카악, 퉤!"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "お前たちのような行儀の悪い若者が引っ搔き回すせいだ。カーッ、ペッ！"
L18_1.m_Talk_JPN = L19_1
L19_1 = "It's messy because rascals like you keep pokin' around! Khaaack, ptooey!"
L18_1.m_Talk_ENG = L19_1
L19_1 = "都是因為你們這種沒規矩的小孩子亂翻的緣故，討厭呸！"
L18_1.m_Talk_TWN = L19_1
L19_1 = "มันเละเทะไปหมดเพราะตัวยุ่งอย่างพวกเธอโผล่มาเลอะเทอะกันเรื่อยเนี่ย! ขากกกกก ทุ้ย!"
L18_1.m_Talk_THA = L19_1
L19_1 = "Thật phiền nhiễu khi mấy đứa nhóc như bọn bay cứ xỏ xiên khắp nơi!! Khạc!"
L18_1.m_Talk_VTN = L19_1
L19_1 = "还不是因为有你们这种没规矩的小孩乱翻东西！嗬——咔啊，呸！"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Es ist hier nur so schmutzig, weil rücksichtslose junge Leute wie ihr, hier herumschnüffeln. Argh! Pfui!"
L18_1.m_Talk_DEU = L19_1
L19_1 = "Si elle est dans cet état, c'est parce que des petits coquins comme vous continuent d'y mettre le foutoir ! Peuh !"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "ESPR2_ACT2_INTERLUDE1@169#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 169
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 4800201
L19_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "OLD_NPC_ESPR2_NULL"
L19_1.m_CharStrID = L20_1
L20_1 = "말해. 내 가게에는 왜 들어왔어?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "言え。俺の店に何で入ってきた？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Tell me, what're y'all doin' in my shop?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "說吧，你們進我的店裡想幹什麼？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ไหนบอกซิ มาทำอะไรในร้านฉันกันล่ะ?"
L19_1.m_Talk_THA = L20_1
L20_1 = "Nào, bọn bay định làm gì trong cửa hàng của tao thế?"
L19_1.m_Talk_VTN = L20_1
L20_1 = "说吧，你们进我的店里想干什么？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Rückt schon raus mit der Sprache. Warum seid ihr in meinen Laden gekommen?"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Parle. Qu'est-ce que vous venez faire ici ?"
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "ESPR2_ACT2_INTERLUDE1@170#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 170
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 4800201
L20_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
