L21_1 = "UNIT_SERIOUS"
L20_1.m_Face = L21_1
L21_1 = "TRUMPET_HARMONY_ESPR2_NULL"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "C"
L21_1 = "으. 저 인간은 왜 바닥에 가래를 뱉어. 더럽게."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "うう。あの人間、なんで床に痰を吐くんだよ。汚いなあ。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Eww, gross... Why'd that guy hock a loogie?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "呃，那個人為什麼要往地板上吐痰啊，髒死了。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "อี๋ ซกมก... ทำไมตาแก่นั่นขากเสลดแบบนั้นเนี่ย?"
L20_1.m_Talk_THA = L21_1
L21_1 = "Eww, kinh quá... Tại sao ông ta nhổ một bãi đờm ra như thế?"
L20_1.m_Talk_VTN = L21_1
L21_1 = "呃，那个人为什么要往地板上吐痰啊，脏死了。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Igitt. Warum spuckt diese Person denn auf den Boden? Wie ekelhaft."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Beurk. Il a craché par terre, là ? C'est carrément dégueu."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "ESPR2_ACT2_INTERLUDE1@171#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 171
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 4800201
L21_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Face = "UNIT_IDLE"
L22_1 = "REGINA_ESPR_NULL_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "C"
L22_1 = "저희는 발렌티누스 수도원이란 곳으로 가는 중입니다."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "私たちはバレンチヌス修道院というところに向かう途中なのです。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "We are on our way to the Valentinus Monastery."
L21_1.m_Talk_ENG = L22_1
L22_1 = "我們要去一個叫聖華倫修道院的地方。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "เรากำลังไปอารามวาเลนตินัสกันน่ะค่ะ"
L21_1.m_Talk_THA = L22_1
L22_1 = "Chúng tôi đang trên đường đến tu viện Valentinus."
L21_1.m_Talk_VTN = L22_1
L22_1 = "我们要去一个叫瓦伦廷修道院的地方。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Wir sind auf dem Weg zum Valentinus-Kloster."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Nous nous dirigeons vers le Monastère de Valentinus."
L21_1.m_Talk_FRA = L22_1
