L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 173
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 4800201
L23_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "OLD_NPC_ESPR2_NULL"
L23_1.m_CharStrID = L24_1
L24_1 = "수도원? 제 발로 그 곳에 간다고?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "修道院？　自分の足でそこに行くだと？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "The monastery? You're tellin' me you headed up there?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "修道院？主動去那個地方？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "อารามเหรอ? จะบอกว่ากำลังไปที่นั่นกันเหรอ?"
L23_1.m_Talk_THA = L24_1
L24_1 = "Tu viện? Bọn bay đang nói với tao là định tới tu viện đó ư?"
L23_1.m_Talk_VTN = L24_1
L24_1 = "修道院？主动去那个地方？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Zum Kloster? Ihr wollt also zu Fuß dorthin gehen?"
L23_1.m_Talk_DEU = L24_1
L24_1 = "Le monastère ? Vous comptez monter là-haut à pied ?"
L23_1.m_Talk_FRA = L24_1
