L25_1 = "ESPR2_ACT2_INTERLUDE1@174#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 174
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 4800201
L24_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "REGINA_ESPR_NULL_NULL"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "C"
L25_1 = "네. 그런데 급하게 오느라 식사를 거르고 말았어요."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "はい。ところで急いでいたので食事ができませんでした。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Yes. But we have not eaten anything on our journey over there."
L24_1.m_Talk_ENG = L25_1
L25_1 = "是的，但是因為來得太急，所以沒吃飯。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ค่ะ แต่จนมาถึงที่นี่แล้วเรายังไม่ได้กินอะไรกันเลย"
L24_1.m_Talk_THA = L25_1
L25_1 = "Đúng. Nhưng chúng tôi chưa được ăn gì trên đường tới đó."
L24_1.m_Talk_VTN = L25_1
L25_1 = "是的，但是因为来得太匆忙，我们没有吃上饭。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Ja. Aber da wir überstürzt aufgebrochen sind, haben wir auf unserer Reise noch gar nichts gegessen."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Oui. Le problème, c'est que nous n'avons rien à manger."
L24_1.m_Talk_FRA = L25_1
