L27_1 = "ESPR2_ACT2_INTERLUDE1@176#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 176
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 4800201
L26_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "OLD_NPC_ESPR2_NULL"
L26_1.m_CharStrID = L27_1
L27_1 = "그렇단 말이지. 재밌겠구만. 아주 재밌겠어."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "そうか。面白い。まったく面白いぞ。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Is that so, eh? Interestin' folks y'all are."
L26_1.m_Talk_ENG = L27_1
L27_1 = "這樣啊。有意思，有意思啊。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "อย่างนั้นเหรอเนี่ย? พวกเธอนี่น่าสนใจดีนะ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Thì sao nhỉ? Câu chuyện hay quá."
L26_1.m_Talk_VTN = L27_1
L27_1 = "这样啊。有意思，有意思……"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Ach echt? Interessant. Ihr seid ein paar echt interessante junge Leute."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Vraiment ? Vous êtes du genre spécial vous, hein ?"
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "ESPR2_ACT2_INTERLUDE1@177#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 177
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 4800201
L27_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "OLD_NPC_ESPR2_NULL"
L27_1.m_CharStrID = L28_1
L28_1 = "구석 찬장에 통조림이 있다. 가져가."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "奥の棚に缶詰がある。持っていけ。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "There's some canned food in the corner cupboard. Take 'em."
L27_1.m_Talk_ENG = L28_1
L28_1 = "角落的櫃子裡有罐頭，你們拿走吧。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "มีอาหารกระป๋องอยู่ที่ตู้ตรงมุมนั่นน่ะ เอาไปสิ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Có tí đồ ăn đóng hộp trong tủ góc. Cứ lấy chúng đi."
L27_1.m_Talk_VTN = L28_1
L28_1 = "角落的橱柜里有罐头，你们拿走吧。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Es gibt ein paar Konserven im Eckschrank. Die könnt ihr euch mitnehmen."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Il me reste quelques conserves dans le placard à l'angle, là-bas. Vous pouvez les prendre."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "ESPR2_ACT2_INTERLUDE1@178#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 178
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 4800201
L28_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "REGINA_ESPR_NULL_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L29_1 = "감사합니다. 그렇다면 계산은 이 반지로……"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "ありがとうございます。ではお会計はこの指輪で……"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Thank you. I would also like to pay with this ring..."
L28_1.m_Talk_ENG = L29_1
L29_1 = "謝謝你，那就用這個戒指結帳吧……"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ขอบคุณนะคะ ฉันอยากจ่ายด้วยแหวนนี่..."
L28_1.m_Talk_THA = L29_1
L29_1 = "Cảm ơn. Tôi cũng muốn thanh toán bằng chiếc nhẫn này..."
L28_1.m_Talk_VTN = L29_1
L29_1 = "谢谢你，那就用这个戒指结账吧……"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Vielen Dank. Ich würde gerne mit diesem Ring bezahlen ..."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Merci. Je n'ai pas d'argent pour vous payer, mais je peux vous donner cette bague..."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
