L31_1 = "ESPR2_ACT2_INTERLUDE1@180#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 180
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 4800201
L30_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "OLD_NPC_ESPR2_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "크흐흐, 계산이 왜 필요해. 너희는 결국 값을 치를 텐데."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "くふふ、金など必要ない。お前らは結局はその対価を払うことになるんだからな。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Kehehe... I don't need your money. You'll be paying for it later."
L30_1.m_Talk_ENG = L31_1
L31_1 = "呵呵呵，不需要結帳，因為你們終究會付出代價。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ฮี่ฮี่ฮี่... ฉันไม่อยากได้เงินเธอหรอก เอาไว้เธอค่อยจ่ายทีหลังแล้วกัน"
L30_1.m_Talk_THA = L31_1
L31_1 = "Kekeke... Tao không cần tiền của tụi bay. Rồi tụi bay sẽ trả sau."
L30_1.m_Talk_VTN = L31_1
L31_1 = "嘿，嘿嘿嘿，不需要结账，因为你们终究会付出代价的。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Hehehe. Ihr braucht dafür nicht zu bezahlen. Schließlich werdet ihr später sowieso den Preis dafür zahlen."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Garde ça, hé hé. Vous finirez par payer, d'une façon ou d'une autre..."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
