L34_1 = "ESPR2_ACT2_INTERLUDE1@183#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 183
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 4800201
L33_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_LAUGH"
L34_1 = "REGINA_ESPR_NULL_NULL"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "이 통조림들은 먹어도 탈이 없겠어요. 언동과 다르게 좋은 분이네요."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "この缶詰は食べても平気そうですわね。言動とは違っていい方ですわ。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "I hope we do not get sick eating this canned food... But he was kinder than I thought he would be."
L33_1.m_Talk_ENG = L34_1
L34_1 = "這些罐頭吃下去應該沒問題吧。雖然一副凶神惡煞的，但他是個好人。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "หวังว่ากินอาหารกระป๋องนี่แล้วเราจะไม่ป่วยนะ... แต่เขาใจดีกว่าที่ฉันคิดอีก"
L33_1.m_Talk_THA = L34_1
L34_1 = "Tôi hy vọng chúng ta không bị ốm khi ăn đồ hộp này... Nhưng lão ta tốt bụng hơn vẻ ngoài đấy."
L33_1.m_Talk_VTN = L34_1
L34_1 = "这些罐头吃下去应该没问题吧。虽然说话凶了些，但他是个好人。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Ich hoffe, wir werden nicht krank, wenn wir dieses Dosenfutter zu uns nehmen. Aber er war freundlicher als erwartet."
L33_1.m_Talk_DEU = L34_1
L34_1 = "J'espère que ces conserves vont pas nous rendre malades... enfin, ce vieil homme était plus aimable que ce que j'imaginais."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "ESPR2_ACT2_INTERLUDE1@184#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 184
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 4800201
L34_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_Face = "UNIT_SURPRISE"
L35_1 = "TRUMPET_HARMONY_ESPR2_NULL"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "방금 저 더러운 늙은이가 의미심장한 말 하는 거 못 들었어? 뭘 아무렇지 않게 넘어가?"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "さっきあの汚い老人の意味深な言葉、聞こえなかった？　疑問に思わないの？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Didn't you hear that old guy say some creepy stuff? What do you mean he was nice?!"
L34_1.m_Talk_ENG = L35_1
L35_1 = "你沒聽到剛才那個髒老頭說的話嗎？那種意味深長的表情，你怎麼能若無其事呢？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ไม่ได้ยินเหรอว่าแต่แก่นั่นพูดอะไรน่าอี๋ออกมาน่ะ? นิสัยดีเดออะไรนะที่ว่า?"
L34_1.m_Talk_THA = L35_1
L35_1 = "Cô không nghe thấy lão già đó nói mấy câu kinh dị sao? Ý cô là lão thật tử tế á?!"
L34_1.m_Talk_VTN = L35_1
L35_1 = "呀！你没听到刚才那个脏老头说的话吗？看到那种意味深长的表情，你还这么若无其事啊？"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Hast du nicht gehört, wie dieser schmutzige alte Mann gerade ein paar echt gruselige Sachen gesagt hat? Wie kannst du das einfach ignorieren?"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Euh, il était surtout effrayant non ? Qu'est-ce que tu entends par « aimable » exactement ?"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
