L38_1 = "ESPR2_ACT2_INTERLUDE1@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 4800201
L37_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_Face = "UNIT_SURPRISE"
L38_1 = "SILKY_NPC_ESPR2_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "R"
L38_1 = "네? 수도원에서 돌아올 때 갚으라는 얘기 아니셨어요?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "え？　修道院から戻ってくる時に払えという意味じゃなかったんですか？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Huh? Didn't he mean that we'd paid for it once we got back from the monastery?"
L37_1.m_Talk_ENG = L38_1
L38_1 = "什麼？不是讓我們從修道院回來的時候，再還錢的意思嗎？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "หา? นั่นไม่ได้หมายความว่าเรากลับจากอารามแล้วค่อยมาจ่ายเหรอคะ?"
L37_1.m_Talk_THA = L38_1
L38_1 = "Hử? Không phải ý ông ta là sau khi quay trở về từ tu viện, chúng ta sẽ trả nợ sao?"
L37_1.m_Talk_VTN = L38_1
L38_1 = "什么？不是让我们从修道院回来的时候，再还账的意思吗？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Wie bitte? Meinte er nicht, dass wir den Preis beglichen hätten, sobald wir aus dem Kloster zurückkämen?"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Hein ? Il a juste dit qu'on le paierait en revenant du monastère, non ?"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "ESPR2_ACT2_INTERLUDE1@188#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 188
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 4800201
L38_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "REGINA_ESPR_NULL_NULL"
L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "L"
L39_1 = "나이 지긋한 노인 분이세요. 허공에 대고 넋두리를 늘어놔도 이상할 것 없어요."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "かなりご年配の方ですもの。あさっての方に向かって愚痴をこぼしてもおかしくはありませんわ。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "He is old and senile. No one would even care if he started grumbling at nothing."
L38_1.m_Talk_ENG = L39_1
L39_1 = "一位上了年紀的老人，對著空氣說三道四，也沒什麼奇怪的。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "แก่ปูนนั้นแล้ว เขาจะบ่นพล่ามอะไรก็ไม่มีใครสนหรอก"
L38_1.m_Talk_THA = L39_1
L39_1 = "Ông ta già và lú lẫn rồi. Dù ông ta có cằn nhằn vô lý chuyện gì thì cũng chẳng ai để ý đâu."
L38_1.m_Talk_VTN = L39_1
L39_1 = "一位上了年纪的老人，对着空气说三道四，也没什么奇怪的。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Er ist ein seniler alter Mann. Ich würde seinen Äußerungen keine allzu große Beachtung schenken."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Il avait l'air un peu sénile, si vous voulez mon avis. Du genre à grogner pour un rien, il ne faut pas faire attention."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "ESPR2_ACT2_INTERLUDE1@189#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 189
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 4800201
L39_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "REGINA_ESPR_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "L"
L40_1 = "통조림은 챙겼으니까 이만 가죠. 운전사 분이 기다리시겠어요."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "缶詰もいただいたことですし、もう行きましょう。運転手さんがお待ちですわ。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "We got our food, so let us get moving. Our driver is waiting."
L39_1.m_Talk_ENG = L40_1
L40_1 = "罐頭已經裝好了，我們走吧。司機還在等我們呢。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "เราได้อาหารแล้วก็ไปกันเถอะ คนขับรถรออยู่นะ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Chúng ta có thức ăn rồi, nên là tiếp tục đi thôi. Người tài xế đang đợi đấy."
L39_1.m_Talk_VTN = L40_1
L40_1 = "罐头已经装好了，我们走吧。司机师傅该等着急了。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Wir haben unser Essen, also lasst uns gehen. Unser Fahrer wartet bestimmt schon."
L39_1.m_Talk_DEU = L40_1
L40_1 = "On a eu ce qu'on voulait, alors mettons-nous en route. Notre chauffeur nous attend."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
