L42_1 = "UNIT_DESPAIR"
L41_1.m_Face = L42_1
L42_1 = "TRUMPET_HARMONY_ESPR2_NULL"
L41_1.m_CharStrID = L42_1
L42_1 = "C_D"
L41_1.m_Pos = L42_1
L42_1 = {}
L43_1 = "ESPR2_ACT2_INTERLUDE1@192#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 192
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 4800201
L42_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "USER_ADMIN_NULL_NULL"
L42_1.m_CharStrID = L43_1
L43_1 = "으음, 저걸 대담하다고 해야 할지 무신경하다고 해야 할지 모르겠군."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "うーむ、大胆というべきか無神経というべきか。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Hmm... I don't know if she's bold or indifferent about the whole thing..."
L42_1.m_Talk_ENG = L43_1
L43_1 = "呃嗯，真不知道該說她是膽子大，還是後知後覺。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "อืม... ทั้งหมดทั้งมวลนี่ไม่รู้แล้วแฮะว่าเธอเก่งหรือเธอโก๊ะ..."
L42_1.m_Talk_THA = L43_1
L43_1 = "Hmm... Tôi không biết là cô ấy liều lĩnh hay thờ ơ với mọi thứ..."
L42_1.m_Talk_VTN = L43_1
L43_1 = "嗯……真不知道该说她是胆子大，还是头脑迟钝。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Hmm. Ich weiß nicht, ob sie sehr mutig oder zu gleichgültig mit der ganzen Sache umgeht ..."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Hmm... j'ai du mal à savoir si c'est du courage ou de la naïveté..."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "ESPR2_ACT2_INTERLUDE1@193#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 193
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 4800201
L43_1.m_CutScenStrID = "ESPR2_ACT2_INTERLUDE1"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "TRUMPET_HARMONY_ESPR2_NULL"
